_HDR_MAP_CACHE: dict = {}


def _hdr_col_map(ws) -> dict:
    """Header lookup by row2 names — robust to column inserts per spec § TEMPLATE_*.xlsx. Cached per worksheet object (the
    pilot never writes headers, USER 2026-09-30): the per-row max_column walk was ~48% of the main thread's GIL time."""
    _hit = _HDR_MAP_CACHE.get(id(ws))
    if _hit is not None and _hit[0] is ws:
        return dict(_hit[1])
    m = _hdr_col_map_scan(ws)
    if len(_HDR_MAP_CACHE) > 256:
        _HDR_MAP_CACHE.clear()
    _HDR_MAP_CACHE[id(ws)] = (ws, m)  # holds the ws: its id can never be reused while cached
    return dict(m)


def _hdr_col_map_scan(ws) -> dict:
    m = {}
    try:
        for c in range(1, ws.max_column + 1):
            hv = ws.cell(row=2, column=c).value
            if hv and isinstance(hv, str):
                hv = hv.strip()
                # map exact header and lowercase variant
                m[hv] = c
                m[hv.lower()] = c
                # also map without spaces for robustness
                m[hv.replace(" ", "_").lower()] = c
        # fallback defaults if header missing (old template compat)
        for k, fallback in [("BASELINE",5),("HUSTLE_DELTA",6),("VECTOR_DELTA",7),("LIVE_DELTA",8),("LIVE_SHARPE",9),("PER_ROW_FILTERS",11),("override",3),("is_default",12)]:
            if k not in m and k.lower() not in m:
                m[k] = fallback
                m[k.lower()] = fallback
    except Exception:
        pass
    return m

def _resolve_cols(ws) -> dict:
    """Resolve E/F/G/H/I/K/C/L columns via header names, fallback to hardcoded."""
    hm = _hdr_col_map(ws)
    # common header variants observed in TEMPLATEs
    def pick(*names, fallback):
        for n in names:
            if n in hm: return hm[n]
            if n.lower() in hm: return hm[n.lower()]
        return fallback
    return {
        "C": pick("override", fallback=3),
        "E": pick("BASELINE", fallback=5),
        "F": pick("HUSTLE_DELTA", "HUSTLE", fallback=6),
        "G": pick("VECTOR_DELTA", "VECTOR", fallback=7),
        "H": pick("LIVE_DELTA", fallback=8),
        "I": pick("LIVE_SHARPE", fallback=9),
        "K": pick("PER_ROW_FILTERS", "PER_ROW_FILTERS", fallback=11),
        "L": pick("is_default", "is_default (backup if bold lost)", fallback=12),
    }

def _clear_vlookup_formulas(ws):
    """Pilot decides — no formulas in data rows r>=3 for C/E/F/G/H/I/K. Clear any VLOOKUP/IF. GLOBAL_RISK_GATES waived only if explicitly documented. Also erase Blanket (page end)."""
    for r in range(3, ws.max_row + 1):
        for col in (3, 5, 6, 7, 8, 9, 11):  # C,E,F,G,H,I,K
            try:
                v = ws.cell(row=r, column=col).value
                if isinstance(v, str) and v.startswith("="):
                    # GLOBAL_RISK_GATES exception: keep G/H/I formulas only if sheet is GLOBAL and col in 7,8,9 and row has no prior calc
                    if ws.title == "GLOBAL_RISK_GATES" and col in (7, 8, 9):
                        continue
                    ws.cell(row=r, column=col).value = None
                # Erase Blanket (page end) from H col8
                if col == 8 and isinstance(v, str) and "Blanket" in v:
                    ws.cell(row=r, column=col).value = None
                    ws.cell(row=r, column=col).fill = __import__("openpyxl").styles.PatternFill(fill_type=None)
            except Exception:
                pass
        # Also check col8 for Blanket even if not in loop (already handled) and any Blanket incols
        try:
            hv = ws.cell(row=r, column=8).value
            if isinstance(hv, str) and "Blanket" in hv:
                ws.cell(row=r, column=8).value = None
                ws.cell(row=r, column=8).fill = __import__("openpyxl").styles.PatternFill(fill_type=None)
        except Exception:
            pass

def _write_per_row_HIK(ws, r, live_delta, live_sharpe, per_row_filters):
    """Per-row K only — H/I deferred until sheet complete per law 2026-09-25 (formulas screw up fill). H=LIVE_DELTA col8, I=LIVE_SHARPE col9, K=PER_ROW_FILTERS col11. K per row, H/I at sheet-complete via backtest_v12_engine."""
    try:
        if ws is None:
            return
        # H/I deferred per law — do NOT write per row (screws up fill, formulas). Only K per row.
        # H col8 and I col9 will be filled when entire sheet complete via backtest_v12_engine parity.
        # K col11
        try:
            ws.cell(row=r, column=11).value = str(per_row_filters) if per_row_filters else None
            ws.cell(row=r, column=11).font = Font(name="Arial", size=10, bold=False)
            ws.cell(row=r, column=11).alignment = VISUAL_ALIGN
        except Exception:
            pass
    except Exception:
        pass

def _auto_adjust_sheet(ws):
    """Auto adjust column width (max len+2 cap 30) and row height 15 per row. Called after _atomic_save."""
    try:
        for col in ws.columns:
            max_len = 0
            col_letter = col[0].column_letter
            for cell in col:
                try:
                    if cell.value is not None:
                        l = len(str(cell.value))
                        if l > max_len:
                            max_len = l
                except Exception:
                    pass
            ws.column_dimensions[col_letter].width = min(max_len + 2, 30)
        for row in ws.iter_rows():
            try:
                ws.row_dimensions[row[0].row].height = 15
            except Exception:
                pass
    except Exception:
        pass

TEMPLATE_STOCKS_LONG = ROOT / "SPREADSHEETS" / "TEMPLATE_FINAL_NORM" / "TEMPLATE_STOCKS_LONG.xlsx"
TEMPLATE_STOCKS_SHORT = ROOT / "SPREADSHEETS" / "TEMPLATE_FINAL_NORM" / "TEMPLATE_STOCKS_SHORT.xlsx"
TEMPLATE_CRYPTO_LONG = ROOT / "SPREADSHEETS" / "TEMPLATE_FINAL_NORM" / "TEMPLATE_CRYPTO_LONG.xlsx"
TEMPLATE_CRYPTO_SHORT = ROOT / "SPREADSHEETS" / "TEMPLATE_FINAL_NORM" / "TEMPLATE_CRYPTO_SHORT.xlsx"
# USER 2026-10-07: 4 INDEPENDENT templates, never a generic one. The legacy
# SPREADSHEETS/TEMPLATE_*.xlsx set is archived (backups/archive_generic_templates_*);
# each cat_side owns its file and they diverge. TEMPLATE alias = STOCKS_LONG norm file.
TEMPLATE = TEMPLATE_STOCKS_LONG


def get_template_for_symside(symside: str) -> Path:
    """4 independent templates (USER 2026-10-07): exact cat_side file, no cross-file fallback."""
    s = symside.upper()
    # strip _LONG/_SHORT suffix before crypto check (ZECUSDC_LONG -> ZECUSDC)
    base = s[:-5] if s.endswith("_LONG") else s[:-6] if s.endswith("_SHORT") else s
    is_crypto = base.endswith(("USDT", "USDC", "USD1", "BUSD", "FDUSD", "TUSD", "DAI"))
    is_long = s.endswith("_LONG")
    # crypto vs stocks, long vs short
    if is_crypto:
        cand = TEMPLATE_CRYPTO_LONG if is_long else TEMPLATE_CRYPTO_SHORT
    else:
        cand = TEMPLATE_STOCKS_LONG if is_long else TEMPLATE_STOCKS_SHORT
    if cand.exists():
        return cand
    raise SystemExit(f"REFUSED: missing template {cand} for {symside} — no cross-side fallback (4 independent templates); restore the file, never substitute another side's")


def _pair_partner_decision(symside, partner_progress_md5, current_md5, template_ok=True, blocked=False):
    """USER 2026-10-14 pair-in-RAM (pure, tested): -> opposite sym_side to calculate in THIS process
    before the symbol leaves RAM, or None. None when the partner is blocked/not tradeable, has no
    template, or was already calculated on the SAME NPZ vintage (md5 equal — cadence owns it then)."""
    s = str(symside or "").upper()
    if s.endswith("_LONG"):
        partner = s[:-5] + "_SHORT"
    elif s.endswith("_SHORT"):
        partner = s[:-6] + "_LONG"
    else:
        return None
    if blocked or not template_ok:
        return None
    if partner_progress_md5 and current_md5 and str(partner_progress_md5) == str(current_md5):
        return None
    return partner


def _pair_blocked(symside, trb_long=None, trb_short=None, mandatory_long=None, mandatory_short=None, non_shortable=None, tradeable_keys=None):
    """True = partner side must never be calculated. USER 2026-10-14 tradeable rule: a STOCKS side is
    tradeable iff its symbol is in symbols_trb_{side}.json OR TRADIER_MANDATORY_{side}_TRB in
    config_tradier (plus NON_SHORTABLE excludes shorts). CRYPTO: present in tradeable_keys.json when
    that file exists. Injected sets are for tests; unreadable sources fail open (scheduler also gates)."""
    s = str(symside or "").upper()
    base = s[:-5] if s.endswith("_LONG") else s[:-6] if s.endswith("_SHORT") else s
    is_crypto = base.endswith(("USDT", "USDC", "USD1", "BUSD", "FDUSD", "TUSD", "DAI"))
    side = "LONG" if s.endswith("_LONG") else "SHORT" if s.endswith("_SHORT") else ""
    if not side:
        return True
    if not is_crypto:
        if side == "SHORT":
            ns = non_shortable
            if ns is None:
                try:
                    import re as _re

                    m = _re.search(r"NON_SHORTABLE\s*=\s*\{([^}]*)\}", (ROOT / "config_tradier.py").read_text())
                    ns = set(_re.findall(r'"([A-Z0-9.\-]+)"', m.group(1))) if m else set()
                except Exception:
                    ns = set()
            if base in ns:
                return True

        def _load(name, injected):
            if injected is not None:
                return set(injected)
            try:
                v = json.loads((ROOT / name).read_text())
                return {str(x).upper() for x in v} if isinstance(v, list) else set()
            except Exception:
                return None

        def _mand(injected, key):
            if injected is not None:
                return set(injected)
            try:
                import re as _re

                m = _re.search(rf"{key}\s*=\s*\[([^\]]*)\]", (ROOT / "config_tradier.py").read_text())
                return set(_re.findall(r'"([A-Z0-9.\-]+)"', m.group(1))) if m else set()
            except Exception:
                return None

        trb = _load(f"symbols_trb_{side.lower()}.json", trb_long if side == "LONG" else trb_short)
        mand = _mand(mandatory_long if side == "LONG" else mandatory_short, f"TRADIER_MANDATORY_{side}_TRB")
        if trb is None and mand is None:
            return False
        return base not in (trb or set()) and base not in (mand or set())
    keys = tradeable_keys
    if keys is None:
        try:
            tk = ROOT / "tradeable_keys.json"
            keys = json.loads(tk.read_text()) if tk.exists() else None
        except Exception:
            keys = None
    if isinstance(keys, list) and keys:
        return not any(str(k).endswith(f":{s}") for k in keys)
    return False


