def _is_red_cell(cell) -> bool:
    try:
        return str(cell.fill.start_color.rgb or "").upper().endswith("FF0000")
    except Exception:
        return False

_ZERO_DEAD_KNOB_MIN_ROWS = 3
_ZERO_SAME_RUN = 6
_ZERO_TAB_FRAC = 0.85
_ZERO_TAB_MIN_ROWS = 20
_ZERO_BH_HALF = 0.5


def _zero_rules_eval(sname: str, ordered: list, by_switch: dict, skipped_by_switch: dict | None = None) -> list:
    """USER 2026-10-11: zero/same-delta detector (pure; shared by pilot paint + sidecar CLI). ordered = [(canon, g_or_None)] in sheet order (MEASURED rows only — callers exclude never-evaluated rows); by_switch = {switch: [(canon, g_or_None)]}. skipped_by_switch = {switch: [canon]} never evaluated. Returns [alert-dicts]. O(rows), no evals — never slows calculations."""
    alerts = []
    try:
        for sw, keys in (skipped_by_switch or {}).items():
            if len(keys) >= _ZERO_DEAD_KNOB_MIN_ROWS:
                alerts.append({"tab": sname, "rule": "SKIP_KNOB", "keys": list(keys), "detail": f"{sw}: {len(keys)} values never evaluated (unwired or skipped — wire it or drop the rows)"})
        nums = [(c, g) for c, g in ordered if isinstance(g, (int, float))]
        if len(nums) >= _ZERO_TAB_MIN_ROWS:
            n0 = sum(1 for _, g in nums if g == 0.0)
            if n0 / len(nums) >= _ZERO_TAB_FRAC:
                alerts.append({"tab": sname, "rule": "ZERO_TAB", "keys": [c for c, _ in nums[:8]], "detail": f"{n0}/{len(nums)} exact-0.0 G (>=85%)"})
        best_run, best_val, best_at = 1, None, 0
        run, run_at = 1, 0
        for i in range(1, len(nums)):
            if nums[i][1] == nums[i - 1][1]:
                run += 1
            else:
                if run > best_run:
                    best_run, best_val, best_at = run, nums[i - 1][1], run_at
                run, run_at = 1, i
        if run > best_run:
            best_run, best_val, best_at = run, nums[run_at][1], run_at
        if best_run >= _ZERO_SAME_RUN:
            alerts.append({"tab": sname, "rule": "SAME_RUN", "keys": [c for c, _ in nums[best_at:best_at + best_run][:8]], "detail": f"{best_run} consecutive identical G={best_val}"})
        for sw, rows in by_switch.items():
            gvals = [(c, g) for c, g in rows if isinstance(g, (int, float))]
            if len(gvals) >= _ZERO_DEAD_KNOB_MIN_ROWS and all(g == gvals[0][1] for _, g in gvals):
                alerts.append({"tab": sname, "rule": "DEAD_KNOB", "keys": [c for c, _ in gvals], "detail": f"{sw}: all {len(gvals)} values delta {gvals[0][1]} (knob does nothing on this window)"})
    except Exception:
        pass
    return alerts


def _rec_measured(rec) -> bool:
    """USER 2026-10-11: a done-rec counts as MEASURED when any eval output exists (vec/trades/yellows/naked/joint). DEAD_VEC_PATH/SKIPPED recs carry none of these."""
    if not isinstance(rec, dict):
        return False
    if rec.get("vec_gain") is not None or rec.get("trades") is not None:
        return True
    if rec.get("yellows") or rec.get("pending_lbI"):
        return True
    return rec.get("naked_delta") is not None or rec.get("joint_delta") is not None


def _zero_bh_eval(gain, bh) -> dict | None:
    """USER 2026-10-11: BH-ratio rule — 15m must beat BH (1x acceptable, <0.5x inexcusable = RED). Returns alert or None."""
    try:
        g, b = float(gain), float(bh)
    except Exception:
        return None
    if b > 0 and g < _ZERO_BH_HALF * b:
        return {"tab": "BASELINE_METRICS", "rule": "BH_HALF", "keys": [], "detail": f"gain {g:.2f}% < 0.5x BH {b:.2f}% (inexcusable)"}
    if b <= 0 and g <= 0:
        return {"tab": "BASELINE_METRICS", "rule": "BH_HALF", "keys": [], "detail": f"gain {g:.2f}% <= 0 with BH {b:.2f}% (inexcusable)"}
    return None

def _paint_tab_status(wb, measured=None) -> dict:
    # tab color = live progress: RED any red/failed row (agent fixes it while the sheet keeps filling),
    # GREEN every switch row has numeric F, ORANGE in progress, untouched = no rows computed yet
    # USER 2026-10-11: zero/same-delta detector rides this same loop (zero extra passes, zero evals — never slows calculations).
    # measured = set of canonical keys actually evaluated (None = unknown, treat numeric as measured; sidecar refines).
    status = {}
    all_alerts = []
    for sname in SWITCH_SHEETS:
        if sname not in wb.sheetnames:
            continue
        ws = wb[sname]
        rows = filled = red = 0
        _ordered, _by_sw, _skipped = [], {}, {}
        _mr, _mc = ws.max_row, ws.max_column  # 2026-10-14 profile: ws.max_column is a full-sheet scan; per-row reads made each save ~41 s (141 s of a 480 s slice)
        for r in range(3, _mr + 1):
            if ws.cell(row=r, column=1).value in (None, ""):
                continue
            rows += 1
            f_cell = ws.cell(row=r, column=6)
            g_cell = ws.cell(row=r, column=7)
            # running-default rows keep F/G blank by design — they count as filled once their yellows are
            if isinstance(f_cell.value, (int, float)) or isinstance(g_cell.value, (int, float)) or any(isinstance(ws.cell(row=r, column=c).value, (int, float)) for c in range(12, _mc + 1)):
                filled += 1
            if _is_red_cell(f_cell) or _is_red_cell(g_cell) or g_cell.value == -1.0:
                red += 1
            try:
                _sw = str(ws.cell(row=r, column=1).value)
                _ck = _canon_key(sname, _sw, ws.cell(row=r, column=2).value)
                if measured is not None and _ck not in measured:
                    _skipped.setdefault(_sw.strip().upper(), []).append(_ck)
                    continue
                _g = g_cell.value if isinstance(g_cell.value, (int, float)) else (f_cell.value if isinstance(f_cell.value, (int, float)) else None)
                _ordered.append((_ck, _g))
                _by_sw.setdefault(_sw.strip().upper(), []).append((_ck, _g))
            except Exception:
                pass
        _zalerts = _zero_rules_eval(sname, _ordered, _by_sw, _skipped)
        all_alerts.extend(_zalerts)
        if red or _zalerts:
            ws.sheet_properties.tabColor = "FF0000"
        elif rows and filled >= rows:
            ws.sheet_properties.tabColor = "00B050"
        elif filled:
            ws.sheet_properties.tabColor = "FFC000"
        status[sname] = {"rows": rows, "filled": filled, "red": red, "zero": [a["rule"] for a in _zalerts]}
    try:
        if all_alerts:
            _write_zero_alerts_sheet(wb, all_alerts)
        elif "ZERO_DELTA_ALERTS" in wb.sheetnames:
            wb["ZERO_DELTA_ALERTS"].sheet_properties.tabColor = "00B050"
    except Exception:
        pass
    status["_zero_alerts"] = all_alerts
    return status


def _write_zero_alerts_sheet(wb, alerts: list):
    """USER 2026-10-11: red flag record — ZERO_DELTA_ALERTS sheet (red tab), full canon keys, no data cells touched."""
    if "ZERO_DELTA_ALERTS" in wb.sheetnames:
        ws = wb["ZERO_DELTA_ALERTS"]
        ws.delete_rows(1, ws.max_row)
    else:
        ws = wb.create_sheet("ZERO_DELTA_ALERTS")
    hdr = ["TAB", "RULE", "CANON_KEYS", "DETAIL"]
    for c, h in enumerate(hdr, 1):
        cell = ws.cell(row=1, column=c, value=h)
        cell.fill = PatternFill(start_color="9C0006", end_color="9C0006", fill_type="solid")
        cell.font = Font(name="Arial", size=10, bold=True, color="FFFFFF")
    for i, a in enumerate(alerts, 2):
        keys = a.get("keys") or []
        ws.cell(row=i, column=1, value=a.get("tab"))
        ws.cell(row=i, column=2, value=a.get("rule"))
        ws.cell(row=i, column=3, value="; ".join(keys[:12]) + ("…" if len(keys) > 12 else ""))
        ws.cell(row=i, column=4, value=a.get("detail"))
        for c in range(1, 5):
            ws.cell(row=i, column=c).fill = PatternFill(start_color="FFC7CE", end_color="FFC7CE", fill_type="solid")
            ws.cell(row=i, column=c).font = Font(name="Arial", size=10, color="9C0006")
    ws.sheet_properties.tabColor = "FF0000"

def _spec_mark_red(wb, sheet: str, r: int, col: int, reason: str):
    """Mark a single yellow cell + tab RED and write reason — for >10s stall per spec."""
    try:
        if sheet not in wb.sheetnames:
            return
        ws = wb[sheet]
        cell = ws.cell(row=r, column=col)
        cell.fill = PatternFill(start_color="FF0000", end_color="FF0000", fill_type="solid")
        cell.font = Font(name="Arial", size=10, bold=True, color="FFFFFF")
        cell.alignment = VISUAL_ALIGN
        if reason:
            cur = str(cell.value or "")
            if not cur or cur.strip() in ("", "0", "0.0"):
                cell.value = reason[:30]
        ws.sheet_properties.tabColor = "FF0000"
    except Exception:
        pass

def _spec_clear_live_formulas(wb):
    """Per spec: LIVE_DELTA/H and LIVE_SHARPE/I contain formulas those screw up sheet fill — clear them to BLANK until workbook complete."""
    for sname in SWITCH_SHEETS:
        if sname not in wb.sheetnames or sname in SKIP_SHEETS:
            continue
        ws = wb[sname]
        cols = _resolve_cols(ws)
        for rr in range(3, ws.max_row + 1):
            for cc in (cols["H"], cols["I"]):
                try:
                    v = ws.cell(row=rr, column=cc).value
                    if isinstance(v, str) and v.startswith("="):
                        ws.cell(row=rr, column=cc).value = None
                        ws.cell(row=rr, column=cc).fill = PatternFill(fill_type=None)
                except Exception:
                    pass

_POOL_PREPARED = None

# Template rows that need several engine keys at once (a sheet row sets one switch). Proven in DC64_GREEDY 2026-09-28.
COMPOSITE_SWITCHES = {
    "WT_DC_DETAILED_TF": lambda tf: {"WT_DC_ENABLED": False} if str(tf).upper() == "OFF" else {"WT_DC_ENABLED": True, "WT_DC_DETAILED_SCORER_ENABLED": True, "WT_DC_TF_ENTRY": str(tf), "WT_DC_DC_TF": str(tf)},
}

def _parse_opt_value(val, default):
    # module-level twin of the per-row _parse_opt in _spec_fill_workbook (same rules)
    if isinstance(val, str) and "=" in val:
        _lh, _rh = val.split("=", 1)
        if _lh.strip() and _lh.strip() == _rh.strip():
            val = _rh.strip()
    if isinstance(default, bool):
        if isinstance(val, bool):
            return val
        if isinstance(val, str):
            s = val.strip().lower()
            if s == "true":
                return True
            if s == "false":
                return False
            if s in ("0", "0.0"):
                return False
            if s in ("1", "1.0"):
                return True
            return val
        if val in (0, 1, 0.0, 1.0):
            return bool(val)
        return val
    if isinstance(default, int) and not isinstance(default, bool):
        try:
            _f = float(str(val))
            return int(_f) if _f.is_integer() else val  # USER 2026-10-13 types lane: never a silent '0.5' -> 0
        except Exception:
            return val
    if isinstance(default, float):
        # USER 2026-10-03 (complete-rounds): config_tradier encodes bools as 0.0/1.0 floats
        # (HTF_GATE_D_MANDATORY, LH_HL_FILTER_REQUIRE_BOTH) — bool-word/native-bool cands coerce honestly.
        if isinstance(val, bool):
            return 1.0 if val else 0.0
        if isinstance(val, str) and val.strip().lower() in ("true", "false"):
            return 1.0 if val.strip().lower() == "true" else 0.0
        try:
            return float(str(val))
        except Exception:
            return val
    if isinstance(val, str) and val.lower() in ("true", "false"):
        return val.lower() == "true"
    return val

DEFAULT_MARKER = "__CONFIG_DEFAULT__"

def _switch_overrides(switch: str, cand_parsed) -> dict:
    if cand_parsed == DEFAULT_MARKER:
        return {}
    return COMPOSITE_SWITCHES[switch](cand_parsed) if switch in COMPOSITE_SWITCHES else {switch: cand_parsed}

_QC_DEFAULT_INST = None


def _config_default_of(field: str):
    """Template lacks a bold default for this field — fall back to the config value for TYPING ONLY
    (never as a value default). Closes the gap where orphans bypassed the type gate and died in the
    engine with a truncated 'override ...' reason (USER 2026-10-03)."""
    global _QC_DEFAULT_INST
    try:
        import config, config_tradier
        for _o in (config.Config, config_tradier.TradierConfig):
            if hasattr(_o, field):
                return getattr(_o, field)
        if _QC_DEFAULT_INST is None:
            import v12_quick_engine as V
            _QC_DEFAULT_INST = V.QuickConfig()
        return getattr(_QC_DEFAULT_INST, field, None)
    except Exception:
        return None


_TYPES_VENUE = [None]  # CRYPTO / STOCKS of the board (set at fill start); None = both surfaces


def _types_coerce_reason(field, value) -> str:
    """USER 2026-10-13 template-types lane: tools/switch_types.coerce(field, value, venue) is the type law. '' = ok, else the
    TYPE_MISMATCH reason. Import/validator failure = TYPE_MISMATCH (fail closed)."""
    try:
        from tools import switch_types as _sty
        _ok, _cv, _why = _sty.coerce(field, value, _TYPES_VENUE[0])
    except Exception as _te:
        return f"TYPE_MISMATCH: switch_types validator unavailable ({_te})"[:200]
    return "" if _ok else f"TYPE_MISMATCH: {_why}"


def _cand_compatible(field: str, cand_parsed, defaults: dict) -> tuple:
    """Type gate: a candidate the engine cannot consume must never be evaluated.

    Returns (ok, reason). Rejects numeric field + non-numeric string (OFF/15m/D),
    dict/list field + scalar (LR_BAND_LADDER_TF_*=1), any '='-containing raw value
    (K=V pollution — a real value never contains '='). Crash-prevention only."""
    if cand_parsed == DEFAULT_MARKER or cand_parsed is None:
        return True, ""
    _tv = _types_coerce_reason(field, cand_parsed)
    if _tv:
        return False, _tv
    if isinstance(cand_parsed, str) and "=" in cand_parsed:
        return False, f"TYPE_MISMATCH: {field} value {cand_parsed!r} contains '=' (K=V pollution, never a real value)"
    default = (defaults or {}).get(field)
    if default is None:
        default = _config_default_of(field)
        if default is None:
            return True, ""
    if isinstance(default, bool):
        if isinstance(cand_parsed, bool):
            return True, ""
        if isinstance(cand_parsed, str) and cand_parsed.strip().lower() in ("true", "false"):
            return True, ""
        if cand_parsed in (0, 1, 0.0, 1.0):
            return True, ""
        return False, f"TYPE_MISMATCH: {field} expects bool, cand {cand_parsed!r}"
    if isinstance(default, int) and not isinstance(default, bool):
        if isinstance(cand_parsed, bool) or isinstance(cand_parsed, (int, float)):
            return True, ""
        if isinstance(cand_parsed, str):
            try:
                int(float(cand_parsed.strip()))
                return True, ""
            except Exception:
                pass
        return False, f"TYPE_MISMATCH: {field} expects int, cand {cand_parsed!r}"
    if isinstance(default, float):
        if isinstance(cand_parsed, bool) or isinstance(cand_parsed, (int, float)):
            return True, ""
        if isinstance(cand_parsed, str):
            try:
                float(cand_parsed.strip())
                return True, ""
            except Exception:
                pass
        return False, f"TYPE_MISMATCH: {field} expects float, cand {cand_parsed!r}"
    if isinstance(default, dict):
        if isinstance(cand_parsed, dict):
            return True, ""
        return False, f"TYPE_MISMATCH: {field} expects dict, cand {cand_parsed!r} (scalar for a dict field — grey per §56.0)"
    if isinstance(default, (list, tuple, set)):
        if isinstance(cand_parsed, (list, tuple, set)):
            return True, ""
        return False, f"TYPE_MISMATCH: {field} expects list, cand {cand_parsed!r}"
    return True, ""

def _switch_type_violation(switch: str, cand, defaults: dict) -> str:
    """'' when the row's expanded override set is type-compatible, else the TYPE_MISMATCH reason."""
    if str(switch).strip() not in COMPOSITE_SWITCHES and cand != DEFAULT_MARKER and cand is not None:
        _tv = _types_coerce_reason(str(switch).strip(), cand)
        if _tv:
            return _tv
    try:
        ov = _switch_overrides(str(switch).strip(), _parse_opt_value(cand, (defaults or {}).get(switch))) or {}
    except Exception:
        return ""
    bad = [_cand_compatible(k, v, defaults)[1] for k, v in ov.items()]
    return "; ".join(r for r in bad if r)

def _clean_ingested_overrides(ov: dict) -> dict:
    """Drop/parse polluted ingested values: 'K=V + ...' multi-strings and single 'K=V'
    strings are column-C display text, never real values. 'X=X' dup typos collapse to X."""
    clean = {}
    for k, v in dict(ov or {}).items():
        if str(k).strip() in GLOBAL_ONLY_KEYS:
            continue  # GLOBAL_ONLY never ingested from start/history/needs_redo/sheets
        if isinstance(v, str) and " + " in v:
            continue
        if isinstance(v, str) and "=" in v:
            _lhs, _rhs = v.split("=", 1)
            _lhs, _rhs = _lhs.strip(), _rhs.strip()
            if not _rhs or "=" in _rhs or "+" in _rhs:
                continue
            if _lhs == _rhs or _lhs == str(k).strip() or not _lhs:
                v = _rhs
            else:
                continue
        clean[k] = v
    return clean

def _pool_eval(overrides: dict, window_days: int):
    # forked worker: prepared NPZ slice inherited copy-on-write from the parent (stays in RAM, no reload)
    import time as _tp
    from tools.opt.v12_pilot import evaluate_prepared_sanitized as _eps
    t0 = _tp.time()
    return _eps(_POOL_PREPARED, overrides, window_days), _tp.time() - t0

def _pool_eval_batch(items: list, window_days: int):
    # batched worker: N evals per pool task (amortizes submit/pickle/collect overhead).
    # Per-item isolation: one bad eval never poisons siblings (each wrapped).
    import time as _tp
    from tools.opt.v12_pilot import evaluate_prepared_sanitized as _eps
    out = {}
    for _ckey, _ov in items:
        _t0 = _tp.time()
        try:
            out[_ckey] = (_eps(_POOL_PREPARED, _ov, window_days), _tp.time() - _t0, "")
        except Exception as _be:
            out[_ckey] = (None, _tp.time() - _t0, f"ERR {_be}"[:120])
    return out

def _pool_eval_ledger(overrides: dict, window_days: int):
    """forked worker for the DIAGNOSE_REPAIR trade autopsy: metrics + compact realised trade rows in gain-pp units."""
    import time as _tp
    from tools.opt.v12_pilot import evaluate_prepared_sanitized as _eps
    from tools import v15_trade_autopsy as _TA
    t0 = _tp.time()
    r = _eps(_POOL_PREPARED, overrides, window_days, True)
    keep = {k: r.get(k) for k in ("gain_pct", "trades", "tim_pct", "max_dd_pct", "wr_pct", "valid", "invalid_reason", "bh_pct", "behavior_fingerprint")}
    keep["_rows"] = _TA.scaled_rows(r)
    return keep, _tp.time() - t0

