def _possym_draw(sym_side: str, tab: str, rkey: str, round_id: str) -> float:
    import hashlib as _hl
    return int(_hl.sha1(f"{sym_side}|{tab}|{rkey}|{round_id}".encode()).hexdigest()[:8], 16) / float(1 << 32)


def _possym_decide(sym_side: str, tab: str, rkey: str, round_id: str, pos, n, new=False):
    """-> (compute: bool, bucket: str, p: float|None, u: float|None). Compute always when the evidence is missing."""
    try:
        pos = int(pos)
    except Exception:
        pos = None
    if new:
        return True, "new_row", None, None
    if pos is None:
        p = _POSSYM_P[0]
        u = _possym_draw(sym_side, tab, rkey, round_id)
        return (u < p), "pos=None", p, u
    if pos is not None and pos >= 1:
        # USER 2026-10-10: every switch/cell with a positive delta in history (pos_sym>=1)
        # is ALWAYS calculated — sampling must never ignore proven-positive moves to save
        # time. Rotation sampling applies ONLY to pos=0/None (never-positive/unknown).
        return True, "pos>=1", None, None
    if pos is not None and pos < 0:
        return True, "pos<0", None, None
    if n is None or int(n) < _POSSYM_MIN_N:
        return True, "n<min_or_unknown", None, None
    p = _POSSYM_P[pos]
    u = _possym_draw(sym_side, tab, rkey, round_id)
    return (u < p), f"pos={pos}", p, u


# ── PRIOR POLICY + SYM_SIDE TIERS + FOCUS ROUND (USER 2026-10-12: "reduce calculation time of the worst_first part by over
# 80% using the daily average delta and pos_sym … second round more specific and larger … winners get most time, mediocre
# and losers go through the sheet lightning fast … bh near zero is mostly a lost case") ──
# Evidence = data/causal/switch_causal_profile.json, mined by tools/v15_switch_causal_profile.py from EVERY fleet delta log
# (2026-10-12: 207 logs, 10.5M real engine evals, 171 sym_sides). Per cat_side it carries, for every SWITCH=cand (naked)
# and every FILTER=opt (marginal vs naked): n_sym, pos_sym, neg_sym, mean/median delta, d_tim, d_trades, verdict
# (USEFUL / SOMETIMES / NEUTRAL / INSUFFICIENT / USELESS / DEAD / HARMFUL). Measured: 82–93% of all eval time sat on keys
# that were never positive on >= 10 sym_sides.
# Law kept: EVERY row still gets its NAKED eval (bible §77, real G, never a fake 0). Only the yellow matrix (96% of evals)
# is pruned: a row/cell whose prior verdict is DEAD / USELESS / HARMFUL on >= V15_PRIOR_MIN_N sym_sides is PRIOR-SKIPPED
# (blank, settled, booked in progress["prior_policy"], NOT hollow — RULE#3 does not refill it) except (a) a rotating
# 1/V15_PRIOR_ROTATE_EVERY slice per round (priors self-correct), (b) sacred / essential-gate / new rows (never pruned),
# (c) PRIOR-REVIVED: a positive naked delta on THIS sym_side runs the skipped yellows on the spot.
# Tiers (progress["tier"]): bh is SIDE-CORRECT (this side's own B&H). WINNER = potential >= max(bh, V15_TIER_WIN_GAIN) or
# bh >= V15_TIER_BIG_MOVER (BH-aligned big movers get the time). USER 2026-10-13: bh <= -V15_TIER_BIG_MOVER means B&H made
# its money on the OPPOSITE side — this side is still calculated in full, but quick (MEDIOCRE/LOSER, post-stages skipped);
# LOST_CAUSE = |bh| < V15_TIER_BH_LOST and no evidence of > V15_TIER_LOST_GAIN; LOSER = potential <= 0 or below
# the trade floor; else MEDIOCRE. LOSER/LOST_CAUSE run STRICT (yellows only on USEFUL/SOMETIMES rows); LOST_CAUSE skips
# the post-stages. The FOCUS round (after the main pass) spends a tier budget only on what moved THIS sym_side.
# Kill switches: V15_PRIOR_POLICY=0 (full board), V15_TIER_FORCE=<tier>, V15_FOCUS_S_<TIER>=0.
_PRIOR_ON = os.environ.get("V15_PRIOR_POLICY", "1") == "1"
_PRIOR_MIN_N = int(os.environ.get("V15_PRIOR_MIN_N", "10") or 10)
_PRIOR_ROTATE_EVERY = int(os.environ.get("V15_PRIOR_ROTATE_EVERY", "25") or 25)
_PRIOR_SKIP_VERDICTS = ("DEAD", "USELESS", "HARMFUL")
_PRIOR_KEEP_VERDICTS = ("USEFUL", "SOMETIMES")
TIERS = ("WINNER", "MEDIOCRE", "LOSER", "LOST_CAUSE")
_TIER_BH_LOST = float(os.environ.get("V15_TIER_BH_LOST", "2.0"))
_TIER_LOST_GAIN = float(os.environ.get("V15_TIER_LOST_GAIN", "5.0"))
_TIER_WIN_GAIN = float(os.environ.get("V15_TIER_WIN_GAIN", "10.0"))
_TIER_BIG_MOVER = float(os.environ.get("V15_TIER_BIG_MOVER", "25.0"))
_TIER_FOCUS_S = {"WINNER": float(os.environ.get("V15_FOCUS_S_WINNER", "900")), "MEDIOCRE": float(os.environ.get("V15_FOCUS_S_MEDIOCRE", "300")), "LOSER": float(os.environ.get("V15_FOCUS_S_LOSER", "120")), "LOST_CAUSE": float(os.environ.get("V15_FOCUS_S_LOST_CAUSE", "0"))}


def _prior_load(cat_side: str) -> dict:
    """{"switch_cand": {...}, "filter_opt": {...}} of one cat_side from the causal profile; {} = no prior (full board)."""
    try:
        f = Path(os.environ.get("V15_PRIOR_JSON") or (Path(__file__).resolve().parent / "data" / "causal" / "switch_causal_profile.json"))
        if not f.exists():
            return {}
        j = json.loads(f.read_text())
        d = ((j.get("cat_sides") or {}).get(cat_side)) or {}
        return d if isinstance(d, dict) else {}
    except Exception:
        return {}


def _prior_entry(prior: dict, kind: str, key: str):
    e = ((prior or {}).get(kind) or {}).get(key)
    return e if isinstance(e, dict) else None


def _prior_skip(entry, min_n: int) -> bool:
    try:
        return bool(entry) and str(entry.get("verdict")) in _PRIOR_SKIP_VERDICTS and int(entry.get("n_sym") or 0) >= int(min_n)
    except Exception:
        return False


def _prior_keep(entry) -> bool:
    try:
        return bool(entry) and str(entry.get("verdict")) in _PRIOR_KEEP_VERDICTS
    except Exception:
        return False


def _prior_rank(entry) -> tuple:
    """coarse-cap rank of a yellow header: (pos_sym, summed positive delta) — proven movers first."""
    try:
        return (int(entry.get("pos_sym") or 0), float(entry.get("sum_pos_delta") or 0.0))
    except Exception:
        return (0, 0.0)


def prior_row_policy(prior: dict, tab: str, switch, cand, hdrs, rr: int, seq: int, every: int, min_n: int, exempt: bool, strict: bool = False):
    """Pure (tests/test_v15_prior_policy.py): -> (mode, kept_hdrs, skipped_hdrs, meta).
    mode 'full' (nothing pruned) | 'rotate' (rotating full re-test of a pruned row) | 'naked_only' (every yellow pruned) |
    'trimmed' (some cells pruned). Row verdict = SWITCH=cand, cell verdicts = FILTER=opt. exempt rows are never pruned.
    strict (LOSER / LOST_CAUSE tiers): yellows only on rows whose prior verdict is USEFUL/SOMETIMES."""
    hdrs = list(hdrs)
    if exempt or not prior or not hdrs:
        return "full", hdrs, [], {"why": "exempt" if exempt else ("no_prior" if not prior else "no_yellows")}
    rot = inert_row_sampled(rr, tab, seq, every)
    rkey = f"{str(switch).strip()}={str(cand).strip()}"
    row_e = _prior_entry(prior, "switch_cand", rkey)
    if _prior_skip(row_e, min_n) or (strict and not _prior_keep(row_e)):
        why = (f"PRIOR_{row_e.get('verdict')}: pos_sym={row_e.get('pos_sym')} in {row_e.get('n_sym')} syms, mean {row_e.get('mean_delta')}" if row_e else "PRIOR_STRICT: no USEFUL/SOMETIMES evidence for this row (tier strict)")
        if rot:
            return "rotate", hdrs, [], {"why": "ROTATE " + why, "verdict": (row_e or {}).get("verdict")}
        return "naked_only", [], hdrs, {"why": why, "verdict": (row_e or {}).get("verdict")}
    kept, skipped, cells = [], [], {}
    for h in hdrs:
        ce = _prior_entry(prior, "filter_opt", str(h).strip())
        if not rot and _prior_skip(ce, min_n):
            skipped.append(h)
            cells[h] = f"PRIOR_{ce.get('verdict')}:pos={ce.get('pos_sym')}/n={ce.get('n_sym')}"
        else:
            kept.append(h)
    return ("trimmed" if skipped else "full"), kept, skipped, {"why": "row kept", "cells": cells, "verdict": (row_e or {}).get("verdict")}


# ---- V17 CARRY (USER 2026-10-14 "99% time savings"): main-pass rows dead (|naked| < eps) on this sym_side's last boards are
# carried (NO-RETEST §65) instead of re-evaluated. Offline replay on the real delta logs (s1+s2, 2026-10-14): rows dead on the
# last 2 boards = 66% of naked rows, 99.3% stayed dead, missed positives 0.27 pp/board. Guards: streak >= 2 evaluated-dead
# boards, last board <= V15_V17_CARRY_MAX_AGE_D (3 d, the NPZ window shift), a carried row is re-evaluated after
# V15_V17_CARRY_MAX_RUN (2) carried boards, rotating 1/V15_V17_CARRY_SAMPLE (10) sample, never WINNER (V15_V17_CARRY_WINNER=0),
# never sacred rows, optional start-set fingerprint match (V15_V17_CARRY_REQUIRE_FP=1).
V17_CUTTABLE_PHASES = frozenset({"P1_PROBE", "P3_FOCUS", "P3_ABLATION", "P3_RETEST", "P3_PROBE", "P3_COMBO", "P3_SURGEON", "P4_FFR", "P4_POST_ENDGAME_DIAG"})  # never REGIME365 / TIMFIX / ESSENTIAL (law); best-start floor / best-seen gate / adopt guards are not phases and always run


def v17_phase_cut_list(path=None) -> set:
    """Phases with n >= V15_V17_CUT_MIN_N (20) new-build boards and ZERO lift on every one (tools/v17_hourly_report.py writes it)."""
    try:
        p = Path(path or os.environ.get("V15_V17_PHASE_STATS", str(Path(__file__).resolve().parent / "data" / "v17_phase_stats.json")))
        d = json.loads(p.read_text())
        n_min = int(os.environ.get("V15_V17_CUT_MIN_N", "20"))
        return {k for k, v in (d.get("phases") or {}).items() if k in V17_CUTTABLE_PHASES and int(v.get("n") or 0) >= n_min and int(v.get("lifted") or 0) == 0}
    except Exception:
        return set()


def carry_key(sheet, switch, cand) -> str:
    return f"{str(sheet).strip()}|{str(switch).strip()}|{str(cand).strip()}"


def carry_start_fp(overrides: dict) -> str:
    import hashlib
    try:
        return hashlib.md5(json.dumps({str(k): str(v) for k, v in dict(overrides or {}).items()}, sort_keys=True).encode()).hexdigest()[:16]
    except Exception:
        return ""


def carry_decide(book: dict, key: str, start_fp: str, now: float, tier: str, sample_seed: int = 0, rotate: bool = True) -> bool:
    """Pure: True when this main-pass row may be carried instead of evaluated."""
    if os.environ.get("V15_V17_CARRY", "1") != "1" or not isinstance(book, dict):
        return False
    if str(tier) == "WINNER" and os.environ.get("V15_V17_CARRY_WINNER", "0") != "1":
        return False
    if now - float(book.get("last_at") or 0.0) > float(os.environ.get("V15_V17_CARRY_MAX_AGE_D", "7")) * 86400.0:
        return False
    if os.environ.get("V15_V17_CARRY_REQUIRE_FP", "0") == "1" and book.get("start_fp") != start_fp:
        return False
    st = (book.get("rows") or {}).get(key)
    if not st or int(st[0]) < 2 or int(st[1]) >= int(os.environ.get("V15_V17_CARRY_MAX_RUN", "2")):
        return False
    if not rotate:
        return True
    n = max(1, int(os.environ.get("V15_V17_CARRY_SAMPLE", "10")))
    import zlib
    return (zlib.crc32(key.encode()) + int(sample_seed)) % n != 0


def carry_update(book: dict, rows: dict, start_fp: str, now: float) -> dict:
    """Pure: rows {key: ("eval", naked_delta) | ("carried", None)} from the board just finished -> new book.
    rows[key] = [evaluated-dead streak, consecutive carried boards]."""
    eps = float(os.environ.get("V15_V17_CARRY_EPS", "1e-6"))
    b = dict(book or {})
    old = dict(b.get("rows") or {})
    if os.environ.get("V15_V17_CARRY_REQUIRE_FP", "0") == "1" and b.get("start_fp") not in (None, start_fp):
        old = {}
    new = {}
    for k, (how, d) in rows.items():
        s0, c0 = (old.get(k) or [0, 0])[:2]
        if how == "carried":
            new[k] = [int(s0), int(c0) + 1]
        elif d is not None:
            new[k] = [int(s0) + 1, 0] if abs(float(d)) < eps else [0, 0]
    b.update(rows=new, start_fp=start_fp, last_at=float(now), boards=int(b.get("boards") or 0) + 1)
    return b


def carry_book_path(symside: str) -> Path:
    return Path(os.path.expanduser(os.environ.get("V15_V17_CARRY_DIR", "~/v15_carry"))) / f"{symside}.json"


def symside_tier(baseline_gain, bh, trades, prior_best=None, floor_trades=10, force=None):
    """Pure (tested). -> (tier, meta). potential = max(baseline gain, best earlier final gain of this sym_side).
    WINNER: potential >= max(bh, WIN_GAIN) with the sample floor, or a BH-ALIGNED BIG MOVER (bh >= BIG_MOVER: B&H made its
    money on THIS side). OPPOSING big mover (bh <= -BIG_MOVER): calculated in full but quick (MEDIOCRE with own gain, else
    LOSER; meta bh_opposing). LOST_CAUSE: flat month (|bh| < BH_LOST) and nothing ever showed > LOST_GAIN. LOSER: potential <= 0 or below the
    trade floor. Else MEDIOCRE. force (V15_TIER_FORCE) overrides for tests/ops."""
    f = (force if force is not None else os.environ.get("V15_TIER_FORCE", "")).strip().upper()
    g = float(baseline_gain or 0.0)
    b = float(bh or 0.0)
    t = int(trades or 0)
    pb = None if prior_best is None else float(prior_best)
    potential = max(g, pb) if pb is not None else g
    meta = {"baseline_gain": round(g, 4), "bh": round(b, 4), "trades": t, "prior_best": pb, "potential": round(potential, 4), "focus_s": None}
    if f in TIERS:
        meta["why"] = f"forced {f}"
        meta["focus_s"] = _TIER_FOCUS_S[f]
        return f, meta
    _win_big = float(os.environ.get("V15_TIER_WIN_BIG_MOVER", "25"))  # USER 2026-10-14: WINNER = real potential, or |bh| >= 25
    if b >= _win_big:
        tier, why = "WINNER", f"big mover bh {b:.2f} >= {_win_big} (BH favours this side)"
    elif b <= -_TIER_BIG_MOVER:
        meta["bh_opposing"] = True
        tier = "MEDIOCRE" if potential > 0.0 and t >= int(floor_trades) else "LOSER"
        why = f"opposing big mover bh {b:.2f} <= -{_TIER_BIG_MOVER}: B&H favours the other side — full board, quick pass"
    elif abs(b) < _TIER_BH_LOST and potential < _TIER_LOST_GAIN:
        tier, why = "LOST_CAUSE", f"flat month |bh| {b:.2f} < {_TIER_BH_LOST} and potential {potential:.2f} < {_TIER_LOST_GAIN}"
    elif potential >= max(b, _TIER_WIN_GAIN) and t >= int(floor_trades):
        tier, why = "WINNER", f"potential {potential:.2f} >= max(bh {b:.2f}, {_TIER_WIN_GAIN}) with {t} trades"
    elif potential <= 0.0 or t < int(floor_trades):
        tier, why = "LOSER", f"potential {potential:.2f} <= 0 or trades {t} < {floor_trades}"
    else:
        tier, why = "MEDIOCRE", f"potential {potential:.2f} between 0 and max(bh {b:.2f}, {_TIER_WIN_GAIN})"
    meta["why"] = why
    meta["focus_s"] = _TIER_FOCUS_S[tier]
    return tier, meta


_LEDGER_CACHE = {}


def _ledger_entry(symside: str):
    """USER 2026-10-14 "winner boards … simply take the best gainers from the previous test round … need almost no resources":
    one read of data/v15_symside_ledger.json (built in 0.1 s from the KPI board table on S1, pushed to the workers) -> this
    sym_side's {sched_tier W/M/L, potential, tier_why}. None when absent (legacy tiering)."""
    try:
        if "d" not in _LEDGER_CACHE:
            f = Path(os.environ.get("V15_LEDGER_JSON") or (ROOT / "data" / "v15_symside_ledger.json"))
            _LEDGER_CACHE["d"] = (json.loads(f.read_text()).get("sym_sides") or {}) if f.exists() else {}
        e = _LEDGER_CACHE["d"].get(symside)
        return e if isinstance(e, dict) and e.get("sched_tier") in ("W", "M", "L") else None
    except Exception:
        return None


def ledger_tier_name(sched_tier: str, bh) -> str:
    """Pure: ledger tier -> pilot tier. W = previous round's best gainers -> WINNER; L -> LOST_CAUSE on a flat month, else LOSER."""
    if sched_tier == "W":
        return "WINNER"
    if sched_tier == "L":
        return "LOST_CAUSE" if abs(float(bh or 0.0)) < _TIER_BH_LOST else "LOSER"
    return "MEDIOCRE"


def _apply_ranking_floor(tier_name: str, tier_meta: dict, symside: str):
    """Pure (tested). USER 2026-10-14: a ranking top-25 winner-long/loser-short is hot NOW, but the
    floor respects what the tier means. LOSER (flat name; the best of them are the favorite SHORTS)
    -> MEDIOCRE full board, quick pass. LOST_CAUSE (near-zero everything, full boards are pure compute
    burn) -> only LOSER: STRICT yellows + small focus, post stages still skipped — a cheap re-measure,
    not a full board. Earned WINNER/MEDIOCRE untouched. Sheet math untouched (compute only)."""
    try:
        if tier_name in ("LOSER", "LOST_CAUSE") and os.environ.get("V15_RANKING_TIER_FLOOR", "1") == "1" and symside:
            from tools.v15_ranking_priority import is_ranking_side as _is_rk
            if _is_rk(symside):
                tier_meta = dict(tier_meta or {})
                if tier_name == "LOST_CAUSE":
                    tier_meta["ranking_floor"] = "loser"
                    tier_meta["focus_s"] = _TIER_FOCUS_S["LOSER"]
                    tier_meta["source"] = "%s+ranking-floor-loser" % (tier_meta.get("source") or "?")
                    return "LOSER", tier_meta
                tier_meta["ranking_floor"] = True
                tier_meta["focus_s"] = _TIER_FOCUS_S["MEDIOCRE"]
                tier_meta["source"] = "%s+ranking-floor" % (tier_meta.get("source") or "?")
                return "MEDIOCRE", tier_meta
    except Exception:
        pass
    return tier_name, tier_meta


def _prior_best_gain(symside: str):
    """Highest top-level final_gain of earlier finished runs of this sym_side (newest 4 progress files + the size-tier
    ledger). Tier evidence only — never a baseline, never a setting."""
    best = None
    try:
        _pst = ROOT / "data" / "persym_size_tiers.json"
        if _pst.exists():
            _e = (json.loads(_pst.read_text()) or {}).get(symside) or {}
            _g30 = _e.get("g30")
            if isinstance(_g30, (int, float)) and not isinstance(_g30, bool):
                best = float(_g30)
    except Exception:
        best = None
    try:
        import glob as _g
        paths = _g.glob(os.path.expanduser(f"~/v15_run*/progress/{symside}_v14_progress.json")) + [str(ROOT / "data" / "reports" / "lifecycle_pilot" / f"{symside}_v14_progress.json")]
        paths = [p for p in paths if os.path.exists(p)]
        paths.sort(key=lambda p: -os.path.getmtime(p))
        for pth in paths[:4]:
            try:
                fg = (json.loads(Path(pth).read_text()) or {}).get("final_gain")
            except Exception:
                continue
            if isinstance(fg, (int, float)) and not isinstance(fg, bool) and (best is None or float(fg) > best):
                best = float(fg)
    except Exception:
        pass
    return best


