def v17_ev(key, know=None, prior=None, kind="switch_cand") -> float:
    """Pure ranking EV of one SWITCH=cand / FILTER=opt: knowledge mean_delta x pos_rate (or its 'ev'), else the causal profile
    mean_delta x pos_sym/n_sym, else 0. Ranking only — never a delta, never written as a result."""
    try:
        e = (know or {}).get(key)
        if isinstance(e, (int, float)) and not isinstance(e, bool):
            return float(e)
        if isinstance(e, (tuple, list)) and len(e) >= 3:
            return float(e[1]) * float(e[2])  # load_ev: (n, mean_delta, pos_rate)
        if isinstance(e, dict):
            if isinstance(e.get("ev"), (int, float)):
                return float(e["ev"])
            md, pr = e.get("mean_delta"), e.get("pos_rate")
            if isinstance(md, (int, float)) and isinstance(pr, (int, float)):
                return float(md) * float(pr)
        pe = ((prior or {}).get(kind) or {}).get(key)
        if isinstance(pe, dict):
            n = int(pe.get("n_sym") or 0)
            return float(pe.get("mean_delta") or 0.0) * (float(pe.get("pos_sym") or 0) / max(1, n))
    except Exception:
        pass
    return 0.0


def v17_top_filters(prior: dict, know: dict | None = None, k: int = 15) -> list:
    """Pure: the top-k filter switch NAMES for one cat_side, ranked by fleet evidence (summed positive deltas of every option,
    naked + as a yellow, + knowledge EV); cold start / thin evidence is filled from V17_FILTER_FALLBACK (board report top-15)."""
    score: dict = {}
    for kind in ("filter_opt", "switch_cand"):
        for key, e in ((prior or {}).get(kind) or {}).items():
            if not isinstance(e, dict) or "=" not in str(key):
                continue
            name = str(key).split("=", 1)[0].strip()
            if not v17_is_filter_key(name):
                continue
            if int(e.get("pos_sym") or 0) <= 0 and int(e.get("promoted_sym") or 0) <= 0:
                continue
            score[name] = score.get(name, 0.0) + float(e.get("sum_pos_delta") or 0.0) + 2.0 * float(e.get("promoted_sym") or 0)
    for key in (know or {}):
        name = str(key).split("=", 1)[0].strip()
        if v17_is_filter_key(name):
            score[name] = score.get(name, 0.0) + max(0.0, v17_ev(key, know))
    ranked = [n for n, _ in sorted(score.items(), key=lambda t: -t[1])]
    out = []
    for n in ranked + list(V17_FILTER_FALLBACK):
        if n not in out:
            out.append(n)
        if len(out) >= max(0, int(k)):
            break
    return out


def v17_tab_order(tabs, prior: dict, tab_keys: dict | None = None) -> list:
    """Pure: P2 tab order by measured lift per eval-second of the cat_side (Σ sum_pos_delta / Σ total_secs over the tab's
    SWITCH=cand keys); tabs without evidence keep the fallback order (board report family ranking). Every tab is kept."""
    tabs = list(tabs)
    fb = {t: i for i, t in enumerate(V17_TAB_ORDER_FALLBACK)}
    sc = (prior or {}).get("switch_cand") or {}
    rate = {}
    for t in tabs:
        lift = secs = 0.0
        for key in (tab_keys or {}).get(t, ()):
            e = sc.get(key)
            if isinstance(e, dict):
                lift += float(e.get("sum_pos_delta") or 0.0)
                secs += float(e.get("total_secs") or 0.0)
        rate[t] = (lift / secs) if secs > 0 else None
    if not any(v is not None for v in rate.values()):
        return sorted(tabs, key=lambda t: fb.get(t, len(fb)))
    return sorted(tabs, key=lambda t: (rate[t] is None, -(rate[t] or 0.0), fb.get(t, len(fb))))


def v17_load_priors(cat_side: str) -> dict:
    """data/causal/v17_priors.json via tools/v17_priors.load(cat_side) (eval-cache / causal-learner mining lane); {} = absent."""
    try:
        from tools.v17_priors import load as _vpl
        d = _vpl(cat_side)
        return d if isinstance(d, dict) else {}
    except Exception:
        return {}


def v17_merge_priors(profile: dict, vp: dict) -> dict:
    """Pure: causal profile + v17_priors, per key the entry with the larger n_sym wins (fail-open: profile alone)."""
    out = {k: dict(v) if isinstance(v, dict) else v for k, v in (profile or {}).items()}
    if not isinstance(vp, dict) or not vp:
        return out
    single = vp.get("single") if isinstance(vp.get("single"), dict) else {}
    for kind in ("filter_opt", "switch_cand"):
        dst = out.setdefault(kind, {})
        src = dict(vp.get(kind) or {})
        for key, e in single.items():
            if isinstance(e, dict) and "=" in str(key) and (kind == "filter_opt") == v17_is_filter_key(str(key).split("=", 1)[0]):
                src.setdefault(key, e)
        for key, e in src.items():
            if not isinstance(e, dict):
                continue
            cur = dst.get(key)
            if not isinstance(cur, dict) or int(e.get("n_sym") or e.get("n") or 0) > int(cur.get("n_sym") or 0):
                ne = dict(e)
                ne.setdefault("n_sym", int(e.get("n") or 0))
                dst[key] = ne
    for extra in ("filter_blocks_switch", "synergy", "deprioritise"):
        if vp.get(extra) is not None:
            out["v17_" + extra] = vp.get(extra)
    return out


def v17_pos_top(prior: dict, min_n: int = 10, pct: float | None = None) -> float:
    """Pure: pos_sym at the pct percentile of the cat_side's evidenced FILTER=opt cells (n_sym >= min_n); >= 1."""
    pct = float(os.environ.get("V15_V17_P_TOP_PCT", "0.97")) if pct is None else float(pct)
    vals = sorted(int(e.get("pos_sym") or 0) for e in ((prior or {}).get("filter_opt") or {}).values() if isinstance(e, dict) and int(e.get("n_sym") or 0) >= int(min_n))
    if not vals:
        return 1.0
    return float(max(1, vals[min(len(vals) - 1, int(pct * len(vals)))]))


def v17_cell_p(entry, top: float, min_n: int = 10) -> float:
    """Pure (USER 2026-10-13 yellow-frequency rule): p = max(1/200, min(1, pos_sym / pos_top)); unevidenced (no entry or
    n_sym < min_n) = 1.0 (fail-open, always evaluated). Floor via V15_V17_P_MIN (default 0.005 = once in 200)."""
    pmin = float(os.environ.get("V15_V17_P_MIN", "0.005"))
    try:
        if not isinstance(entry, dict) or int(entry.get("n_sym") or 0) < int(min_n):
            return 1.0
        return max(pmin, min(1.0, float(entry.get("pos_sym") or 0) / max(1.0, float(top))))
    except Exception:
        return 1.0


def v17_cell_keep(cat_side, tab, switch, cand, hdr, seq, p) -> bool:
    """Pure deterministic draw: md5(cat_side|tab|switch=cand|hdr|seq) -> u in [0,1); keep iff u < p. The round seq rotates
    the draw, so every cell is re-evaluated about once in 1/p rounds."""
    if p >= 1.0:
        return True
    import hashlib as _hl
    u = int(_hl.md5(f"{cat_side}|{tab}|{str(switch).strip()}={str(cand).strip()}|{str(hdr).strip()}|{seq}".encode()).hexdigest()[:12], 16) / float(16 ** 12)
    return u < float(p)


def v17_merge_exemptions(base, add) -> dict:
    """Pure: union-merge FILTER_EXEMPTIONS dicts {path: [filters]} (chain value + new exemption), order-stable, no duplicates."""
    out = {}
    for src in (base, add):
        if not isinstance(src, dict):
            continue
        for path, fl in src.items():
            cur = out.setdefault(str(path), [])
            for f in (fl if isinstance(fl, (list, tuple)) else [fl]):
                if f not in cur:
                    cur.append(f)
    return out


def v17_killers(eff_without, eff_by_filter: dict, frac: float = 0.5) -> list:
    """Pure ATTRIBUTE step: filters whose restoration kills (or more than halves) a switch's delta discovered on the stripped
    base. eff_without = g(strip+sw) - g(strip); eff_by_filter[f] = g(strip+f+sw) - g(strip+f) (None = no verdict)."""
    try:
        ew = float(eff_without)
    except Exception:
        return []
    if ew <= 1e-9:
        return []
    out = []
    for f, e in (eff_by_filter or {}).items():
        if isinstance(e, (int, float)) and not isinstance(e, bool) and float(e) < ew * float(frac):
            out.append(f)
    return sorted(out, key=lambda f: float(eff_by_filter[f]))


def v18_parts_to_overrides(parts, defaults: dict):
    """[(key, raw value)] of one V18 path (digest winner / repair-menu path / ablation remedy) -> (delta override set, '') or
    (None, refusal reason). Refused, never a candidate: GLOBAL_ONLY, ABLATION_* (a lever, never a setting), MAXAUG 0, unwired,
    *_ALT, type law (tools/switch_types), not a config field, promotion-blocked (DEAD_VEC / LIVE_ONLY / ...), hard-set,
    protective stop OFF, engine artefacts (MODE / VENUE / ...)."""
    dov = {}
    for k, raw in parts or []:
        k = str(k).strip()
        if not k:
            return None, "EMPTY_KEY"
        if k in GLOBAL_ONLY_KEYS:
            return None, f"GLOBAL_ONLY:{k}"
        if k.startswith("ABLATION_"):
            return None, f"ABLATION_IS_A_LEVER:{k}"
        if k == "MAX_AUGMENTS_PER_POSITION" and _maxaug_is_zero(str(raw)):
            return None, "MAXAUG_NEVER_ZERO"
        if k in UNWIRED_SWITCHES or k in UNWIRED_FILTERS:
            return None, f"NOT_WIRED_VEC:{k}"
        if isinstance(raw, str) and raw.strip().upper().endswith("_ALT"):
            return None, f"INVENTED_ALT:{k}"
        _tv = _switch_type_violation(k, raw, defaults)
        if _tv:
            return None, _tv
        try:
            pv = raw if isinstance(raw, (dict, list)) else _parse_opt_value(raw, (defaults or {}).get(k))
        except Exception:
            return None, f"PARSE:{k}"
        sub = _switch_overrides(k, pv) or {}
        if not sub:
            continue
        for k2 in sub:
            if k2 not in known_config_fields():
                return None, f"NOT_IN_CONFIG:{k2}"
        _blk = promotion_block_reason(k, None)
        if _blk:
            return None, _blk
        dov.update(sub)
    if not dov:
        return None, "EMPTY"
    _why = _V18P.deny_reason(dov) if _V18P is not None else ""
    if _why:
        return None, _why
    return dov, ""


V17_P3_MIN_SHARE = {"WINNER": 0.5, "MEDIOCRE": 0.4, "LOSER": 0.25, "LOST_CAUSE": 0.1}
V17_P3_MAX_DEFAULT = {"WINNER": 1500.0, "MEDIOCRE": 540.0, "LOSER": 300.0, "LOST_CAUSE": 120.0}


def v17_p3_cap(tier: str) -> float:
    """USER 2026-10-13 "extend time cap for winners" + "the 0.3 rule": INITIAL pinpoint budget per tier (V15_V17_P3_MAX_S_<TIER>:
    WINNER 1500 / MEDIOCRE 540 / LOSER 300 / LOST_CAUSE 120 s); the round then extends in chunks for as long as the last window
    lifted >= V15_V17_MIN_LIFT_PM (no absolute cap, see v17_p3_hard). An explicitly set V15_V17_P3_MAX_S overrides every tier.
    Tier = symside_tier (big movers |bh| >= V15_TIER_BIG_MOVER are WINNER)."""
    if os.environ.get("V15_V17_P3_MAX_S"):
        return float(os.environ["V15_V17_P3_MAX_S"])
    t = str(tier or "LOSER").upper()
    return float(os.environ.get(f"V15_V17_P3_MAX_S_{t}", V17_P3_MAX_DEFAULT.get(t, 300.0)))


def v17_p3_hard() -> float:
    """Absolute pinpoint wall: none (inf) unless V15_V17_P3_MAX_S is explicitly set (USER 2026-10-13 "never kill a backtest as
    long as it manages to keep it up")."""
    v = os.environ.get("V15_V17_P3_MAX_S")
    return float(v) if v else float("inf")


def v17_p3_extend(rate_pm: float, now: float, deadline: float, window_s: float, hard: float) -> float:
    """Pure: new pinpoint deadline after a window that lifted rate_pm pp/min. Lifting >= V15_V17_MIN_LIFT_PM and the deadline
    within 120 s -> extend by one chunk (max(V15_V17_P3_CHUNK_S 180 s, the window just measured)), clipped only by hard."""
    if rate_pm < float(os.environ.get("V15_V17_MIN_LIFT_PM", "0.3")) or deadline - now >= 120.0 or now >= hard - 60.0:
        return deadline
    return min(hard, now + max(float(os.environ.get("V15_V17_P3_CHUNK_S", "180")), float(window_s)))


def v17_p3_budget(tier: str, elapsed: float, board_s: float | None = None, tail_s: float | None = None) -> float:
    """Pure: pinpoint budget is NEVER starved by a long main pass (A/B 2026-10-13: 3 of 4 boards got 0 s). Guaranteed minimum
    = board target x tier share (WINNER 50% / MEDIOCRE 40% / LOSER 25% / LOST_CAUSE 10%, V15_V17_P3_SHARE_<TIER>); more when the
    board is ahead of its target (V15_V17_BOARD_S 1500 s minus the tail V15_V17_TAIL_S 210 s); hard cap V15_V17_P3_MAX_S 900 s.
    The pinpoint loop may extend past it while it keeps lifting >= V15_V17_MIN_LIFT_PM pp/min (still <= the hard cap)."""
    b = float(board_s if board_s is not None else os.environ.get("V15_V17_BOARD_S", "1500"))
    t = float(tail_s if tail_s is not None else os.environ.get("V15_V17_TAIL_S", "210"))
    share = float(os.environ.get(f"V15_V17_P3_SHARE_{tier}", V17_P3_MIN_SHARE.get(str(tier), 0.25)))
    guaranteed = b * share
    return max(0.0, min(v17_p3_cap(tier), max(guaranteed, b - float(elapsed) - t)))


def same_val(a, b) -> bool:
    """Module-level twin of _spec_fill_workbook._same_val (identical body) for standalone drivers (s6 365D+GS)."""
    if isinstance(a, bool) or isinstance(b, bool) or str(a).lower() in ("true", "false") or str(b).lower() in ("true", "false"):
        return str(a).strip().lower() == str(b).strip().lower()
    try:  # USER 2026-10-07: exact-equality fast path — abs(inf-inf)=nan made inf NEVER equal inf (MOVER_ACCOUNT phantom)
        fa, fb = float(a), float(b)
        return fa == fb or abs(fa - fb) < 1e-12
    except Exception:
        return str(a).strip() == str(b).strip()


def _canon_val(v) -> str:
    """USER 2026-10-11: canonical setting value — identity is FULL NAME + VALUE, never row/col. 2.0==2, True==TRUE, off==OFF."""
    if isinstance(v, bool):
        return "TRUE" if v else "FALSE"
    s = str(v).strip() if v is not None else ""
    if s.lower() in ("true", "false", "off", "on", "none"):
        return s.upper()
    try:
        f = float(s)
        return str(int(f)) if f.is_integer() else repr(f)
    except Exception:
        return s


def _canon_key(tab: str, switch: str, cand) -> str:
    """USER 2026-10-11: canonical cross-run identity TAB!SWITCH=value (row numbers shift daily by obligation — never identity)."""
    return f"{str(tab).strip()}!{str(switch).strip().upper()}={_canon_val(cand)}"


def _canon_key_of_done(done_key: str):
    """Parse a stored done-key (TAB!row:SWITCH=value, any row) into its canonical identity. None if unparseable."""
    try:
        tab, rest = str(done_key).split("!", 1)
        sw_val = rest.split(":", 1)[1]
        sw, val = sw_val.split("=", 1)
        return _canon_key(tab, sw, val)
    except Exception:
        return None


def _done_canon_lookup(done: dict, tab: str, switch: str, cand, row=None, _cache: dict | None = None):
    """USER 2026-10-11: cross-run done lookup by canonical identity (never row). Exact row-key first (fast, stable-template path), then canonical scan. Dup canonical matches prefer the embedded row, else first sorted. Returns (rec, matched_key) or (None, None)."""
    if not isinstance(done, dict) or not done:
        return None, None
    if row is not None:
        exact = f"{tab}!{row}:{switch}={cand}"
        if exact in done:
            return done[exact], exact
    want = _canon_key(tab, switch, cand)
    cmap = None
    if _cache is not None and _cache.get("n") == len(done) and isinstance(_cache.get("map"), dict):
        cmap = _cache["map"]
    else:
        cmap = {}
        for k in done:
            ck = _canon_key_of_done(k)
            if ck is not None:
                cmap.setdefault(ck, []).append(k)
        if _cache is not None:
            _cache["map"] = cmap
            _cache["n"] = len(done)
    cands = cmap.get(want) or []
    if not cands:
        return None, None
    if len(cands) == 1:
        return done[cands[0]], cands[0]
    if row is not None:
        for k in sorted(cands):
            try:
                if int(str(k).split("!", 1)[1].split(":", 1)[0]) == int(row):
                    return done[k], k
            except Exception:
                continue
    best = sorted(cands)[0]
    return done[best], best


def scan_template_cands(template_path, defaults: dict, cat_side: str, zero_on: bool = True) -> tuple:
    """Standalone mirror of the pilot's per_tab_rows + header_maps + orange scan and the _row_static KIND decision
    (USER 2026-10-07 s6: the 365D+GS driver needs the same candidate space as in-pilot diagnose/graph-search).
    Returns ([{tab,row,switch,cand,ov,orange,blocked}], stats). Structural skips + ZERO_FORMULA condemned rows are
    excluded exactly like the pilot; possym SAMPLING is deliberately NOT applied (s6 tests the full evaluable space).
    Template-embedded POS/N fallback columns are not read (fleet JSON evidence wins, same as the pilot's first source).
    This function only enumerates moves — every number still comes from a real v12 engine eval in the caller."""
    import openpyxl as _oxl
    stats = {"rows": 0, "eval": 0, "skip": 0, "zero_skipped": 0, "filters": 0}
    _zm = _possym_load_nsym(cat_side) if zero_on else {}
    wb = _oxl.load_workbook(template_path, read_only=False, data_only=True)  # USER 2026-10-07: read_only random .cell() access grinds (100% CPU, 7+ min); normal mode like the pilot parses in seconds
    try:
        tabs = [s for s in wb.sheetnames if s in SWITCH_SHEETS and s not in SKIP_SHEETS]
        per_tab, orange, hmaps = {}, set(), {}
        for sname in tabs:
            ws = wb[sname]
            cols = _resolve_cols(ws)
            rows = []
            for rr in range(3, ws.max_row + 1):
                sw = ws.cell(row=rr, column=1).value
                if sw is None or (isinstance(sw, str) and sw.strip() == ""):
                    continue
                sw = str(sw).strip()
                if sw.lower() in ("switch", "general", "blanket", "filter", "option value") or sw.startswith("—"):
                    continue
                cand = ws.cell(row=rr, column=2).value
                if cand is None:
                    cand = defaults.get(sw)
                    cand = DEFAULT_MARKER if cand is None else cand
                if isinstance(cand, str) and cand.strip().lower() in ("option value", "sheets applicable", "gates"):
                    continue
                try:
                    if str(ws.cell(row=rr, column=1).fill.fgColor.rgb or "").upper().endswith("FFE699"):
                        orange.add((sname, rr))
                except Exception:
                    pass
                try:
                    _isdef = str(ws.cell(row=rr, column=cols["L"]).value or "").strip().upper() == "YES"
                except Exception:
                    _isdef = False
                rows.append((rr, sw, cand, _isdef))
            rows.sort(key=lambda x: (sname, x[0]) in orange)
            per_tab[sname] = rows
            hm = {}
            for cc in range(12, ws.max_column + 50):
                try:
                    hv = ws.cell(row=2, column=cc).value
                except Exception:
                    hv = None
                if hv and isinstance(hv, str) and "=" in hv and not hv.upper().startswith("WHAT SWITCH"):
                    hm[hv.strip()] = cc
                if hv and isinstance(hv, str) and hv.strip().upper().startswith("WHAT SWITCH"):
                    break
            hmaps[sname] = hm
    finally:
        try:
            wb.close()
        except Exception:
            pass
    cands, seen = [], set()
    for sname in tabs:
        for rr, sw, cand, _isdef in per_tab.get(sname, []):
            stats["rows"] += 1
            if (sw, str(cand)) in seen:
                continue
            if cand is None or str(cand).strip() in ("", "None", "none"):
                stats["skip"] += 1
                continue
            if str(sw).strip() in UNWIRED_SWITCHES or str(sw).strip() in UNWIRED_FILTERS:
                stats["skip"] += 1
                continue
            if str(cand).strip().upper().endswith("_ALT"):
                stats["skip"] += 1
                continue
            try:
                _ov_probe = _switch_overrides(str(sw).strip(), _parse_opt_value(cand, defaults.get(sw))) or {str(sw).strip(): None}
            except Exception:
                stats["skip"] += 1
                continue
            if not all(k in known_config_fields() for k in _ov_probe):
                stats["skip"] += 1
                continue
            try:
                if _switch_type_violation(str(sw).strip(), cand, defaults):
                    stats["skip"] += 1
                    continue
            except Exception:
                pass
            if zero_on and not _isdef:
                _zrkey = f"{sname}!{str(sw).strip()}={str(cand).strip()}"
                _zjr = _zm.get(_zrkey)
                if isinstance(_zjr, dict) and _low_yield_on():
                    if not str(sw).strip().startswith(SACRED_ZERO_EXEMPT_PREFIXES) and str(sw).strip() not in ESSENTIAL_GATE_SWITCHES and not low_yield_keep(_zjr.get("pos_sym"), _zjr.get("n_sym"), _ZERO_MIN_N_ROW, _zrkey, datetime.datetime.utcnow().strftime("%Y%m%d"))[0]:
                        stats["skip"] += 1
                        stats["zero_skipped"] += 1
                        continue
                elif isinstance(_zjr, dict) and _zero_condemned(_zjr.get("pos_sym"), _zjr.get("n_sym"), _ZERO_MIN_N_ROW):
                    stats["skip"] += 1
                    stats["zero_skipped"] += 1
                    continue
            try:
                ov = _switch_overrides(sw, _parse_opt_value(cand, defaults.get(sw)))
            except Exception:
                stats["skip"] += 1
                continue
            if not ov:
                stats["skip"] += 1
                continue
            seen.add((sw, str(cand)))
            cands.append({"tab": sname, "row": rr, "switch": sw, "cand": cand, "ov": ov, "orange": (sname, rr) in orange, "blocked": promotion_block_reason(sw, sname)})
            stats["eval"] += 1
    for sname in tabs:
        for hdr in hmaps.get(sname, {}):
            filt, opt = [x.strip() for x in hdr.split("=", 1)]
            if (filt, opt) in seen or filt not in known_config_fields() or filt in UNWIRED_FILTERS or filt in UNWIRED_SWITCHES:
                continue
            try:
                val = _parse_opt_value(opt, defaults.get(filt))
                if not _cand_compatible(filt, val, defaults)[0]:
                    continue
            except Exception:
                continue
            seen.add((filt, opt))
            cands.append({"tab": sname, "row": None, "switch": filt, "cand": opt, "ov": {filt: val}, "orange": True, "blocked": promotion_block_reason(filt, sname)})
            stats["filters"] += 1
    return cands, stats


def delta_vs_result(res, cum_before: float):
    """Module-level twin of the fill loop's _delta_vs (pure — extracted 2026-10-03 for testing).
    (delta, promotable, reason): real gain delta always reported; engine-invalid results keep
    their delta but never promote."""
    if not res or res.get("gain_pct") is None:
        return None, False, str((res or {}).get("invalid_reason") or "no result")[:40]
    if int(res.get("trades") or 0) == 0:
        return None, False, "ZERO_TRADES"
    d = float(res.get("gain_pct")) - cum_before
    d = 0.0 if abs(d) < 1e-9 else d
    if not res.get("valid"):
        return d, False, str(res.get("invalid_reason") or "invalid")[:40]
    return d, True, ""


def _spec_fill_workbook(new_symside: str, wb_path: Path, progress: dict, progress_path: Path, flags_md: Path, cumulative_gain: float, cumulative_overrides: dict, defaults: dict, baseline_gain: float, bh: float, prepared, args, baseline_vec: dict, baseline_live: dict):
    """Sequential spec filler (USER 2026-09-29 late, BACKTEST_BIBLE §56 rev b): 13 tabs in order, every row in order
    (white switch rows, then orange filter rows), no row skipped, no tab jumping.
    - Running set = bold defaults + previous-best overrides (column C); its real gain = E3 (chain start).
    - Per row: every yellow = running set + switch=cand + that filter, delta vs the LATEST baseline, always written.
      Positive yellows -> PER_ROW_FILTERS (K). VECTOR_DELTA (G) = complete row delta vs LATEST baseline (switch + all
      positive filters, real joint eval); blank only on the running-default row without positive yellows.
      HUSTLE_DELTA (F) = same result vs the ORIGINAL baseline.
    - G > 0 -> promote, next row's E = latest baseline + G; otherwise the next row's E stays EMPTY. E only goes up.
    - Slow cell (> YELLOW_TIMEOUT) -> logged + RED, fill continues; reds retried at the end.
    - LIVE_DELTA/H and LIVE_SHARPE/I stay BLANK until workbook DONE, then filled via backtest_v12_engine on the winning set.
    Returns updated cumulative_gain, cumulative_overrides, progress.
    """
    import time as _t
    # USER 2026-10-12 TIERS: where this sym_side sits (vs B&H, vs its own best, sample) decides how much time it gets (symside_tier).
    try:
        _tier_trades = int((baseline_live or {}).get("trades") or (baseline_vec or {}).get("trades") or 0)
    except Exception:
        _tier_trades = 0
    _TYPES_VENUE[0] = "STOCKS" if map_key_for_symside(new_symside).startswith("STOCKS") else "CRYPTO"
    _led = _ledger_entry(new_symside) if os.environ.get("V15_TIER_SOURCE", "ledger") == "ledger" and not os.environ.get("V15_TIER_FORCE") else None
    if _led is not None:
        _tier_name, _tier_meta = symside_tier(baseline_gain, bh, _tier_trades, _led.get("potential"), floor_trades=ADAPT_FLOOR_TRADES, force=ledger_tier_name(_led.get("sched_tier"), bh))
        _tier_meta["why"] = f"ledger {_led.get('sched_tier')} (previous round): {_led.get('tier_why')}"
        _tier_meta["source"] = "ledger"
    else:
        _tier_name, _tier_meta = symside_tier(baseline_gain, bh, _tier_trades, _prior_best_gain(new_symside), floor_trades=ADAPT_FLOOR_TRADES)
        _tier_meta["source"] = "legacy"
    # USER 2026-10-14 (ranking top-25): hot-now symbols get at least a full MEDIOCRE board, never lightning.
    _tier_name, _tier_meta = _apply_ranking_floor(_tier_name, _tier_meta, new_symside)
    _carry_book, _carry_rows, _carry_fp = {}, {}, ""
    try:
        _carry_fp = carry_start_fp(sanitize_overrides(dict(cumulative_overrides), defaults)[0])
        if carry_book_path(new_symside).exists():
            _carry_book = json.loads(carry_book_path(new_symside).read_text())
    except Exception as _cbe:
        print(f"[V17-CARRY-WARN] book {_cbe}", flush=True)
    _tier_focus_s = float(_tier_meta.get("focus_s") or 0.0)
    _tier_strict = _tier_name in ("LOSER", "LOST_CAUSE") and os.environ.get("V15_TIER_STRICT", "1") == "1"
    _tier_skip_post = (_tier_name in ("LOST_CAUSE", "LOSER") or bool(_tier_meta.get("bh_opposing"))) and os.environ.get("V15_TIER_SKIP_POST", "1") == "1"  # 2026-10-13 throughput: LOSER too
    progress["tier"] = {"tier": _tier_name, **_tier_meta, "strict": _tier_strict, "skip_post": _tier_skip_post, "at": utcnow()}
    print(f"[TIER] {new_symside} {_tier_name}: {_tier_meta.get('why')} -> focus {_tier_focus_s:.0f}s strict={_tier_strict} skip_post={_tier_skip_post}", flush=True)
    import random as _rnd
    import concurrent.futures as _cf
    from openpyxl.styles import PatternFill as _PF, Font as _FT
    # Load workbook once, keep open per spec (wb_keep)
    try:
        wb = openpyxl.load_workbook(str(wb_path), data_only=False)
    except Exception as e:
        print(f"[spec-fill] failed to open {wb_path} {e}", flush=True)
        return cumulative_gain, cumulative_overrides, progress
    # Clear LIVE formulas at start
    try:
        _spec_clear_live_formulas(wb)
    except Exception:
        pass
    try:
        chain_tim = float((baseline_vec or {}).get("tim_pct"))
    except Exception:
        chain_tim = None
    try:
        chain_trades = int((baseline_vec or {}).get("trades") or 0)
    except Exception:
        chain_trades = None
    # Ensure header L:BI uses is_default backup handling — restore bold if lost (is_default col12 = YES means default bold)
    try:
        for sname in SWITCH_SHEETS:
            if sname not in wb.sheetnames or sname in SKIP_SHEETS:
                continue
            ws = wb[sname]
            cols = _resolve_cols(ws)
            c_isdef = cols["L"]
            for rr in range(3, ws.max_row + 1):
                isdef = str(ws.cell(row=rr, column=c_isdef).value or "").strip().upper()
                if isdef == "YES":
                    try:
                        ws.cell(row=rr, column=cols["C"]-1).font = Font(name="Arial", size=10, bold=True)
                        ws.cell(row=rr, column=cols["C"]-1).alignment = VISUAL_ALIGN
                    except Exception:
                        pass
    except Exception:
        pass
    fast_switches = None
    if getattr(args, "fast_switches", None):
        fast_switches = set(json.loads(Path(args.fast_switches).read_text()))
        print(f"[spec-fill] FAST mode: {len(fast_switches)} switches from {args.fast_switches}", flush=True)
    # Build per-tab row queues in order (stable) — hustle => shuffled copy
    is_hustle = getattr(args, "seq_mode", "") in ("hustle", "shuffle")
    # USER 2026-09-30: ONE chain in WORKBOOK tab order — ENTRY_REVERSAL_BOUNCE E3 = start, every next tab continues from
    # the previous tab's final baseline
    tabs = [s for s in wb.sheetnames if s in SWITCH_SHEETS and s not in SKIP_SHEETS]
    # Keep defined order as in SWITCH_SHEETS (already 12, STDEV skipped)
    per_tab_rows: dict[str, list] = {}
    orange_rows: set = set()  # GENERAL blanket rows (orange col A) — evaluated as ONE block per tab vs the cumulative
    for sname in tabs:
        ws = wb[sname]
        cols = _resolve_cols(ws)
        rows = []
        for rr in range(3, ws.max_row + 1):
            sw = ws.cell(row=rr, column=1).value
            if sw is None or (isinstance(sw, str) and sw.strip() == ""):
                continue
            sw = str(sw).strip()
            if sw.lower() in ("switch", "general", "blanket", "filter", "option value") or sw.startswith("—"):
                continue
            cand = ws.cell(row=rr, column=2).value
            if cand is None:
                # template row without a default value: test it AT its real config default (never skip the row)
                cand = defaults.get(sw)
                cand = DEFAULT_MARKER if cand is None else cand
            if isinstance(cand, str) and cand.strip().lower() in ("option value", "sheets applicable", "gates"):
                continue
            # 2026-09-28 FIX: DO NOT SKIP GENERAL rows — they need evaluation too!
            # Old code skipped GENERAL, causing per_tab_rows to be missing 75% of rows
            # fam = str(ws.cell(row=rr, column=4).value or "")
            # if fam.upper() == "GENERAL" or sw.upper() == "GENERAL":
            #     continue  # REMOVED - was causing 90% row loss
            # Check is_default backup to know bold default rows — but we still process every row
            if fast_switches is not None and sw not in fast_switches:
                continue  # --fast-switches: left pending for a later full pass on the same sheet
            if str(ws.cell(row=rr, column=1).fill.fgColor.rgb or "").upper().endswith("FFE699"):
                orange_rows.add((sname, rr))
            rows.append((rr, sw, cand))
        if is_hustle:
            _rnd.shuffle(rows)
        # white switch rows are always filled before orange filter rows (a mis-ordered template cannot change that)
        rows.sort(key=lambda x: (sname, x[0]) in orange_rows)
        per_tab_rows[sname] = rows
    # V17 ROUNDS (bible §95): on for fresh boards (or boards that started under V17); a legacy board resumed mid-fill keeps
    # its pre-V17 semantics to the end (no mixed chain). Tab order of P2 = measured lift per eval (persisted: resume-stable).
    _v17 = progress.setdefault("v17", {}) if V17_ON else {}
    _v17_main_done = any(isinstance(_dk, str) and _dk.split("!", 1)[0] in SWITCH_SHEETS for _dk in (progress.get("done") or {}))
    _v17_on = bool(V17_ON and fast_switches is None and prepared is not None and not is_hustle and (_v17.get("on") or not _v17_main_done))
    if V17_ON and not _v17_on:
        print(f"[V17] {new_symside} V17 rounds OFF for this board (legacy resume / fast / hustle / no prepared NPZ)", flush=True)
        if not _v17.get("on"):
            progress.pop("v17", None)
    _v17_t = {"p2_start": None}
    _v17_ptop = [1.0]
    _v17_hv_filters: set = set()
    _v17_ystats = {"evaluated": 0, "skipped": 0}
    _v17_evals = [0]
    if _v17_on:
        _v17["on"] = True
        _v17.setdefault("phases", {})
        _v17.setdefault("started_utc", utcnow())
        _v17["p0_wall_s"] = round(_t.time() - _PILOT_T0, 1)
        try:
            if os.environ.get("V15_V17_TAB_ORDER", "0" if _V17_P2_LEGACY else "1") == "1":
                if not (isinstance(_v17.get("tab_order"), list) and set(_v17["tab_order"]) == set(tabs)):
                    _tk = {s: [f"{str(sw).strip()}={str(cd).strip()}" for (_r, sw, cd) in per_tab_rows.get(s, [])] for s in tabs}
                    _v17["tab_order"] = v17_tab_order(tabs, _prior_load(map_key_for_symside(new_symside)), _tk)
                tabs = list(_v17["tab_order"])
        except Exception as _toe:
            print(f"[V17-WARN] tab order {_toe} — workbook order kept", flush=True)
        print(f"[V17] {new_symside} ON tier={_tier_name} tabs={tabs}", flush=True)
    # Helper to find next pending row index for a tab
    # FIX 2026-09-26: Handle row number mismatch after worksheet resorting
    _done_ids_cache: dict = {}
    def _next_pending(sname: str):
        # Exact (sheet, switch=cand) match survives row resorting; substring match falsely marked
        # "DC_ENABLED=True" done via "WT_DC_ENABLED=True" and "X=1" via "X=10".
        # USER 2026-10-11: canonical compare (2.0==2, TRUE==True) — daily template reorders must not force recalcs.
        done = progress.get("done", {})
        if _done_ids_cache.get("n") != len(done):
            _done_ids_cache["ids"] = {_canon_key_of_done(k) for k in done if "!" in k and ":" in k} - {None}
            _done_ids_cache["n"] = len(done)
        done_ids = _done_ids_cache["ids"]
        for (rr, sw, cand) in per_tab_rows.get(sname, []):
            if _canon_key(sname, sw, cand) in done_ids:
                continue
            return (rr, sw, cand)
        return None
    def _any_pending() -> bool:
        for sname in tabs:
            if _next_pending(sname) is not None:
                return True
        return False
    def _write_E(sname: str, rr: int, value: float):
        cell = wb[sname].cell(row=rr, column=_resolve_cols(wb[sname])["E"])
        cell.value = float(value)
        cell.font = Font(name="Arial", size=10, bold=False)
        cell.alignment = VISUAL_ALIGN
    nav_mode = getattr(args, "nav_mode", "jump")
    # DELTA-LOG (user 2026-09-28): one JSON line per v12_quick eval — proves every delta was really computed
    _delta_log_path = progress_path.parent / "v15_delta_log" / f"{new_symside}_{nav_mode}.jsonl"
    _delta_log_path.parent.mkdir(parents=True, exist_ok=True)
    _delta_log_fh = open(_delta_log_path, "a", buffering=1)
    print(f"[delta-log] {_delta_log_path}", flush=True)
    # V18_SET_SHA (store join, 2026-10-20): boards restart dozens of times per run and BOARD_CTX carried only a behaviour
    # fingerprint -> sha256 of the canonical full sanitized set in force on BOARD_CTX / ROW_DONE / ROW_SETTLED, and every
    # restart's start set once in progress["start_sets"][ts] (sha) + progress["sets_by_sha"][sha] (dict, stored once)
    _v18_setsha_on = bool(_V18P is not None and _V18P.flag_on("V18_SET_SHA"))
    _v18_sha_cache = {"key": None, "sha": None}
    def _v18_set_sha(ov=None):
        try:
            _so = sanitize_overrides(dict(cumulative_overrides if ov is None else ov), defaults)[0]
            return _V18P.set_sha256(_so), _so
        except Exception:
            return None, None
    def _v18_chain_sha():
        # cached per chain version (every promotion bumps _spec_state["ver"]); the set in force AFTER the row (as cum_after)
        try:
            _k = (id(cumulative_overrides), _spec_state["ver"])
        except Exception:
            _k = (id(cumulative_overrides), len(cumulative_overrides or {}))
        if _v18_sha_cache["key"] != _k:
            _v18_sha_cache["key"], _v18_sha_cache["sha"] = _k, _v18_set_sha()[0]
        return _v18_sha_cache["sha"]
    _v18_start_sha = None
    if _v18_setsha_on:
        try:
            _v18_start_sha, _v18_start_set = _v18_set_sha()
            if _v18_start_sha:
                progress.setdefault("start_sets", {})[utcnow()] = {"sha": _v18_start_sha, "n_keys": len(_v18_start_set or {})}
                progress.setdefault("sets_by_sha", {}).setdefault(_v18_start_sha, _v18_start_set)
        except Exception as _sse:
            print(f"[V18-SETSHA-WARN] {_sse}", flush=True)
    try:  # BRAIN 2026-10-14: one board-context line per run (tier/bh/baseline/start-set) — the context the graph conditions on
        _delta_log_fh.write(json.dumps({**({"set_sha256": _v18_start_sha} if _v18_setsha_on else {}), "ts": utcnow(), "sym_side": new_symside, "label": "BOARD_CTX", "cat_side": map_key_for_symside(new_symside), "tier": _tier_name, "bh": bh, "baseline_gain": baseline_gain, "baseline_trades": _tier_trades, "n_overrides": len(cumulative_overrides or {}), "start_fp": _carry_fp, "window_days": args.window_days, "round": os.environ.get("V15_DEFAULTS_ROUND", "")}, default=str) + "\n")
    except Exception as _bce:
        print(f"[BRAIN-WARN] board ctx {_bce}", flush=True)
    # BRAIN (USER 2026-10-14 "like a neural network … lower the number of times per 1000 tests low scorers are calculated"):
    # one learned model (tools/v15_brain.py, nightly export data/brain/brain_<CAT_SIDE>.json) decides per cell — and with
    # V15_BRAIN_NAKED=1 per row — p_eval = clip(P(pos)/p_ref, floor/1000, 1); deterministic draw, propensity booked in
    # progress["brain"]; skipped cells ride prior_skipped (PRIOR-REVIVED on a positive naked); skipped rows are settled
    # BRAIN_SAMPLED_OUT (like CARRIED_DEAD). Never: sacred / essential-gate / new / coarse-expand rows, WINNER-tier rows.
    # 2026-10-14 USER: speed first, but "only allow a modification if results improve" -> ON only via the version gate's flags
    # file (tools/v15_version_gate.py PASS on the frozen-NPZ bench); p_ref 0.005 / floor 5 per 1000. Bible §108.
    _brain = None
    if os.environ.get("V15_BRAIN", "0") == "1":  # default comes from data/v15_gate_flags.json (gate PASS only, USER 2026-10-14) — env wins
        try:
            from tools.v15_brain import PilotBrain as _PilotBrain, draw as _brain_draw
            _brain_path = Path(os.environ.get("V15_BRAIN_DIR") or (ROOT / "data" / "brain")) / f"brain_{map_key_for_symside(new_symside)}.json"
            if _brain_path.exists():
                _brain = _PilotBrain(str(_brain_path), new_symside)
                print(f"[BRAIN] {new_symside} model {_brain_path.name} built {_brain.meta.get('at')} p_ref {_brain.p_ref} floor {_brain.floor * 1000:.1f}/1000 naked={os.environ.get('V15_BRAIN_NAKED', '0')}", flush=True)
            else:
                print(f"[BRAIN] no model {_brain_path} — full board", flush=True)
        except Exception as _bre:
            print(f"[BRAIN-WARN] load {_bre} — full board", flush=True)
            _brain = None
    _brain_naked = _brain is not None and os.environ.get("V15_BRAIN_NAKED", "0") == "1" and (_tier_name != "WINNER" or os.environ.get("V15_BRAIN_NAKED_WINNER", "0") == "1")
    _brain_rid = f"{os.environ.get('V15_DEFAULTS_ROUND', '')}|{utcnow()[:10]}"
    _brain_book = progress.setdefault("brain", {"rows": {}, "cells": {}, "stats": {}}) if _brain is not None else {"rows": {}, "cells": {}, "stats": {}}
    _brain_stats = _brain_book.setdefault("stats", {})
    for _bk in ("rows_seen", "rows_out", "cells_seen", "cells_out", "observed"):
        _brain_stats.setdefault(_bk, 0)
    # Row-parallel evals: naked + every yellow of a row are independent (all vs the same cumulative_before), so they are
    # prefetched in a forked process pool; results keyed by label, failures -> None + reason (never -1/0). Joint stays serial.
    global _POOL_PREPARED
    _pool = None
    _n_proc = max(1, min(int(getattr(args, "workers", 1) or 1), (os.cpu_count() or 2) - 1))
    os.environ["V15_RESULT_WORKERS"] = str(_n_proc)
    if prepared is not None and _n_proc > 1:
        import multiprocessing as _mp
        _POOL_PREPARED = prepared
        _pool = _cf.ProcessPoolExecutor(max_workers=_n_proc, mp_context=_mp.get_context("fork"), initializer=_pool_worker_sig_default)
        # 2026-09-28 fork-deadlock fix: ProcessPoolExecutor forks workers LAZILY at first submit,
        # which lands after threads exist (red-fixer/eval threads) — a fork while another thread
        # holds a lock leaves children in futex_wait forever (s2 herd froze at load 3.8, logs idle
        # 26-52min). Force ALL workers to fork NOW, while this process is still single-threaded.
        list(_pool.map(abs, range(_n_proc * 4)))
        print(f"[spec-fill] process pool {_n_proc} workers (fork, NPZ shared, pre-forked single-threaded)", flush=True)
    _prio_pool = None
    if _priority_lane_on() and _pool is not None:  # TASK 05.2 priority lane (USER 2026-10-15): critical-path eval
        # fetch goes to a 1-worker pool forked AFTER preload (inherits _POOL_PREPARED) instead of the shared FIFO.
        # V15_PRIORITY_LANE=0 (default) = shared FIFO exactly as before. Same _pool_eval_batch -> exact outputs.
        import multiprocessing as _mp_prio
        _prio_pool = _cf.ProcessPoolExecutor(max_workers=1, mp_context=_mp_prio.get_context("fork"), initializer=_pool_worker_sig_default)
        list(_prio_pool.map(abs, range(4)))
        print("[spec-fill] priority lane ON: 1-worker pool for critical-path evals", flush=True)
    # USER 2026-09-30: every RED (stuck/slow) cell and every 0 delta is logged for the fixing agent
    _zr_path = progress_path.parent / "v15_zero_red" / f"{new_symside}.jsonl"
    _zr_path.parent.mkdir(parents=True, exist_ok=True)
    _zr_fh = open(_zr_path, "a", buffering=1)
    def _zr_log(rec: dict):
        try:
            _zr_fh.write(json.dumps({"ts": utcnow(), "sym_side": new_symside, **rec}, default=str) + "\n")
        except Exception:
            pass
    def _delta_log(rec: dict):
        try:
            _delta_log_fh.write(json.dumps(rec, default=str) + "\n")
        except Exception:
            pass
    # E4 2026-10-20 (doc 17 §4.1/§4.3/§3.4): kill switches V18_IDENTITY_SETTLE / V18_IO_THROTTLE / V18_LEDGER_WRITEBACK, default OFF
    _v18_ids = _V18P.IdentityBook() if (_V18P is not None and _V18P.identity_settle_on()) else None
    _v18_io = bool(_V18P is not None and _V18P.io_throttle_on())
    _v18_wb = {"on": bool(_V18P is not None and _V18P.ledger_writeback_on()), "pending": [], "ver": None, "tag": None, "capture": None}
    _v18_logx = [bool(_V18P is not None and any(_V18P.flag_on(_k) for _k in ("V18_BRAIN", "V18_WINNERS", "V18_EXIT_REPAIR", "V18_ABLATION", "V18_FLOOR", "V18_MUST", "V18_PROFILE_YELLOWS", "V18_LINKNET_FIRST")))]  # E8 hook §4: brain_p / brain_model / phase on every eval line
    _v18_lx: dict = {}  # label -> extra delta-log fields of a V18 phase eval (companions / family / remedy_class / from_cat_side)
    if _v18_ids is not None or _v18_io or _v18_wb["on"]:
        print(f"[V18] {new_symside} identity_settle={_v18_ids is not None} io_throttle={_v18_io} ledger_writeback={_v18_wb['on']}", flush=True)
    def _v18_settle_row(sname: str, rr: int, switch, cand, key: str, cum_before: float):
        summ = _v18_ids.end_row()
        if not summ:
            return
        progress["done"][key]["settled"] = dict(summ["settled"])
        _delta_log(_V18P.row_settled_record({**({"set_sha256": _v18_chain_sha()} if _v18_setsha_on else {}), "ts": utcnow(), "sym_side": new_symside, "nav": nav_mode, "sheet": sname, "row": rr, "switch": switch, "cand": str(cand), "cum_before": cum_before}, summ))
    def _v18_capture():
        if _spec_state["ver"] != _v18_wb["ver"]:
            _v18_wb["ver"] = _spec_state["ver"]
            _v18_wb["pending"].append(("PROMOTED", _v18_wb["tag"] or f"ver{_spec_state['ver']}", dict(cumulative_overrides)))
            _v18_wb["tag"] = None
    def _v18_writeback():
        if not _v18_wb["on"] or prepared is None:
            return
        try:
            from tools.opt.v12_pilot import evaluate_prepared_sanitized as _eps_w
            _book = progress.setdefault("v18_trade_log", {"written": []})
            _done_keys = {(w.get("kind"), w.get("sha")) for w in (_book.get("written") or [])}
            _pend = [(k, tg, sanitize_overrides(dict(ov), defaults)[0]) for k, tg, ov in _v18_wb["pending"]] + [("FINAL", "final", sanitize_overrides(dict(cumulative_overrides), defaults)[0])]
            _plan, _capped = _V18P.plan_writeback(_pend, _done_keys, int(os.environ.get("V18_LEDGER_MAX_EVALS", "40")))
            _npz_path = _run_npz_id.get("path") if isinstance(_run_npz_id, dict) else None
            _npz_md5 = _V18P.file_md5(_npz_path) if _npz_path else None
            _out = _V18P.trade_log_path(progress_path.parent, new_symside)
            _t0w = _t.time()
            for _sha, _ov, _kinds in _plan:
                _res = _eps_w(prepared, _ov, args.window_days, include_ledger=True)
                for _kind, _tag in _kinds:
                    _V18P.append_jsonl(_out, _V18P.trade_log_record(_kind, _tag, new_symside, map_key_for_symside(new_symside), _ov, _res, args.window_days, _npz_md5, _run_npz_short, utcnow()))
                    _book["written"].append({"kind": _kind, "tag": _tag, "sha": _sha, "gain_pct": (_res or {}).get("gain_pct"), "trades": (_res or {}).get("trades")})
            _v18_wb["pending"] = []
            _book["path"], _book["capped"], _book["secs"] = str(_out), int(_book.get("capped", 0)) + int(_capped), round(float(_book.get("secs", 0.0)) + _t.time() - _t0w, 3)
            print(f"[V18-LEDGER] {new_symside} {len(_plan)} ledger evals ({sum(len(k) for _, _, k in _plan)} records, capped {_capped}) -> {_out} in {_t.time() - _t0w:.2f}s", flush=True)
        except Exception as _we:
            print(f"[V18-LEDGER-WARN] {new_symside} write-back failed: {_we} — board unaffected", flush=True)
    initial_baseline = float(progress.setdefault("initial_baseline_gain", float(baseline_gain)))
    # HUSTLE_DELTA (F) = the row measured on its own against the ORIGINAL set (independent eval), never the chain position
    initial_overrides = dict(progress.setdefault("initial_overrides", dict(cumulative_overrides)))
    def _div_col(ws) -> int:
        # DELTA_VS_INITIAL_BASELINE: best REAL measured gain of the row minus the initial baseline (no extra evals) —
        # comparable across rows when the sheet is not filled in order (hustle). Appended after the last header.
        hm = _hdr_col_map(ws)
        if "DELTA_VS_INITIAL_BASELINE" in hm:
            return hm["DELTA_VS_INITIAL_BASELINE"]
        c = max((cc for cc in range(1, ws.max_column + 1) if ws.cell(row=2, column=cc).value not in (None, "")), default=ws.max_column) + 1
        ws.cell(row=2, column=c).value = "DELTA_VS_INITIAL_BASELINE"
        _HDR_MAP_CACHE.clear()  # header written: header maps re-scan
        ws.cell(row=2, column=c).font = Font(name="Arial", size=10, bold=True)
        return c
    div_cols = {sname: _div_col(wb[sname]) for sname in tabs}
    def _write_div(sname: str, rr: int, gains: list):
        gains = [g for g in gains if g is not None]
        if not gains:
            return None
        v = float(max(gains)) - initial_baseline
        cell = wb[sname].cell(row=rr, column=div_cols[sname])
        cell.value = v
        cell.font = Font(name="Arial", size=10, bold=False, color="006100" if v > 1e-9 else "9C0006")
        cell.alignment = VISUAL_ALIGN
        return v
    _last_save = {"t": _t.time()}
    def _zero_flush_book():
        try:
            if not _zero_book_enabled():
                return
            _zb_rows = _zero_book.get("rows") or {}
            _zb_crows = _zero_book.get("cell_rows") or {}
            _zb_hdrs = _zero_book.get("cells_by_header") or {}
            _sig = (len(_zb_rows), len(_zb_crows), sum(len(v) for v in _zb_crows.values()))
            if _sig == _zero_flushed.get("sig"):
                return
            _zero_flushed["sig"] = _sig
            _led = ROOT / "data" / "zero_formula_book" / _ps_cat / f"{new_symside}.json"
            _led.parent.mkdir(parents=True, exist_ok=True)
            _tmp = _led.with_suffix(".json.tmp")
            _tmp.write_text(json.dumps({"symside": new_symside, "cat": _ps_cat, "at": utcnow(), "rows": _zb_rows, "cell_rows": _zb_crows, "cells_total": sum(len(v) for v in _zb_crows.values())}))
            os.replace(_tmp, _led)
            print(f"[ZERO-FORMULA] book flushed rows={len(_zb_rows)} cellrows={len(_zb_crows)} cells={sum(len(v) for v in _zb_crows.values())}", flush=True)
        except Exception as _zfe:
            print(f"[ZERO-FORMULA-WARN] flush failed {_zfe}", flush=True)
    def _maybe_save(at_tab_boundary: bool = False):
        # a full openpyxl save of the ~2.5MB workbook costs ~10s — per-row saves made rows 12s instead of ~1s.
        # progress JSON (source of truth, written every row) + refill_from_json cover a crash between saves.
        if _v18_io and not _V18P.xlsx_save_allowed(_v18_io, at_tab_boundary):
            return
        if _t.time() - _last_save["t"] >= XLSX_SAVE_EVERY_S:
            try:
                _zero_flush_book()
                _atomic_save(wb, wb_path)
            except Exception as _se:
                print(f"[spec-save-warn] {_se}", flush=True)
            _last_save["t"] = _t.time()
    _last_json = {"t": _t.time()}
    def _maybe_write_json(force: bool = False):
        # full rewrite of a progress JSON that grows every row is O(rows^2); the append-only DELTA-LOG keeps every eval,
        # so the JSON is written every PROGRESS_JSON_EVERY_S, on every promotion, and at the end.
        if _SHUTDOWN["v"]:  # USER 2026-10-07: graceful exit at row boundary (this is the live spec-row choke point) — persist first, never corrupt
            try: _atomic_write_json(progress_path, progress)
            except Exception: pass
            raise V15Shutdown("shutdown in fill")
        _slice_s = float(os.environ.get("V15_FILL_SLICE_S", "2400"))  # USER 2026-10-07: NO CALC >40 min — fill time-slices, resume is instant (holes-only)
        if _slice_s > 0 and not _SLICE_HOLD["v"] and progress.get("final_gain") is None and progress.get("diagnose_repair") is None and (_t.time() - _PILOT_T0) > _slice_s:
            try: _atomic_write_json(progress_path, progress)
            except Exception: pass
            try: _atomic_save(wb, wb_path)  # USER 2026-10-07: slice saves the workbook so resume continues (no hollow-redo); shutdown path skips this (OOM: speed+RAM)
            except Exception as _se: print(f"[SLICE-save-warn] {_se}", flush=True)
            print(f"[SLICE] {new_symside} fill hit {_slice_s:.0f}s cap — clean exit, scheduler relaunches into holes-only resume", flush=True)
            sys.exit(11)
        if _v18_wb["capture"] is not None:
            _v18_wb["capture"]()
        if _flush_due(_last_json["t"], _flush_interval_s("V15_PROGRESS_JSON_EVERY_S", PROGRESS_JSON_EVERY_S), _t.time(), force):
            _atomic_write_json(progress_path, progress)
            _last_json["t"] = _t.time()
    try:  # TASK 04.1 forward score (USER 2026-10-15): on refresh boards, BEFORE the main pass, score the PREVIOUS
        # published set + each promoted key leave-one-out on bars added since that board's NPZ end. SCORING ONLY
        # (zero extra fits) -> FORWARD delta-log records + progress['forward']. V15_FORWARD_SCORE=0 (default) = inert.
        if forward_score_on():
            _fw_end = None
            try:
                _fw_ts = (prepared or {}).get("npz_prepared", {}).get("timestamps") or []
                _fw_end = float(_fw_ts[-1]) if len(_fw_ts) else None
            except Exception:
                _fw_end = None
            if _fw_end is None:
                try:
                    _fw_nid = progress.get("npz_id") or {}
                    _fw_end = float(_fw_nid.get("ts_last")) if _fw_nid.get("ts_last") is not None else None
                except Exception:
                    _fw_end = None
            if _fw_end is not None:
                run_forward_score(new_symside, _fw_end, defaults, delta_log_fn=_delta_log, progress=progress)
                _maybe_write_json()
    except Exception as _fwe:
        print(f"[FORWARD-WARN] {new_symside} {_fwe} — main pass unaffected", flush=True)
    def _row_done(sname: str, rr: int, switch: str, cand, n_evals: int, delta, promoted: bool):
        _delta_log({**({"set_sha256": _v18_chain_sha()} if _v18_setsha_on else {}), "ts": utcnow(), "sym_side": new_symside, "nav": nav_mode, "sheet": sname, "row": rr, "switch": switch, "cand": str(cand), "label": "ROW_DONE", "row_secs": round(_t.time() - _row_t0, 4), "n_evals": n_evals, "delta": delta, "promoted": promoted, "cum_after": cumulative_gain})
    def _final_filter_recheck():
        # Before closing: re-run EVERY distinct orange filter=opt against the FINAL cumulative "just in case" (earlier
        # tabs tested them vs an older cumulative). All deltas (pos/neg) -> FINAL_FILTER_RECHECK sheet + progress + log;
        # the single best positive is promoted. This is the per-filter data for row reduction / 365D runs.
        nonlocal cumulative_gain, cumulative_overrides
        cum0 = float(cumulative_gain)
        t0 = _t.time()
        seen = {}
        for (sn, r2) in sorted(orange_rows):
            sw2 = wb[sn].cell(row=r2, column=1).value
            c2 = wb[sn].cell(row=r2, column=2).value
            if sw2 in (None, "") or c2 is None:
                continue
            if _v17_on and os.environ.get("V15_V17_FFR_TOUCHED", "1") == "1" and str(sw2).strip() not in _v17_touched:
                continue  # V17 P4: only filters touched in P1/P3 (run32: 476k of 520k untouched-filter rechecks were exact 0)
            seen.setdefault((str(sw2).strip(), str(c2)), [])
            seen[(str(sw2).strip(), str(c2))].append(f"{sn}!{r2}")
        items = []
        for (sw2, c2) in seen:
            v = dict(cumulative_overrides)
            v.update(_switch_overrides(sw2, _parse_opt_value(c2, defaults.get(sw2))))
            items.append((sw2, c2, sanitize_overrides(v, defaults)[0]))
        results = {}
        futs = {}
        for sw2, c2, v in items:
            ck = (tuple(sorted((k, str(x)) for k, x in v.items())), args.window_days, id(prepared))
            if ck in _EVAL_CACHE:
                results[(sw2, c2)] = (_EVAL_CACHE[ck], "", True)
            elif _pool is not None:
                futs[(sw2, c2)] = (_pool.submit(_pool_eval, v, args.window_days), ck)
            else:
                from tools.opt.v12_pilot import evaluate_prepared_sanitized
                res = evaluate_prepared_sanitized(prepared, v, args.window_days)
                _EVAL_CACHE[ck] = res
                results[(sw2, c2)] = (res, "", False)
        deadline = t0 + YELLOW_TIMEOUT * max(1, -(-len(futs) // max(1, _n_proc)))
        for key, (fut, ck) in futs.items():
            try:
                res, _secs = fut.result(timeout=max(0.01, deadline - _t.time()))
                _EVAL_CACHE[ck] = res
                results[key] = (res, "", False)
            except _cf.TimeoutError:
                fut.cancel()
                results[key] = (None, f"TIMEOUT {YELLOW_TIMEOUT:.0f}s", False)
            except Exception as e:
                results[key] = (None, f"ERR {e}"[:120], False)
        if "FINAL_FILTER_RECHECK" in wb.sheetnames:
            del wb["FINAL_FILTER_RECHECK"]
        fws = wb.create_sheet("FINAL_FILTER_RECHECK")
        hdr = ["filter", "option", "gain_pct", "trades", "valid", "delta_vs_final", "promoted", "cumulative_final_before", "rows", "reason"]
        for i, h in enumerate(hdr, 1):
            fws.cell(row=1, column=i, value=h).font = Font(name="Arial", size=10, bold=True)
        recs = []
        best = None
        for (sw2, c2) in seen:
            res, err, cached = results.get((sw2, c2), (None, "missing", False))
            g = (res or {}).get("gain_pct")
            d = (float(g) - cum0) if g is not None else None
            d = 0.0 if d is not None and abs(d) < 1e-9 else d
            ok = d is not None and bool((res or {}).get("valid"))
            recs.append([sw2, c2, g, (res or {}).get("trades"), (res or {}).get("valid"), d, False, cum0, ", ".join(seen[(sw2, c2)][:6]), err or (res or {}).get("invalid_reason") or ""])
            _delta_log({"ts": utcnow(), "sym_side": new_symside, "nav": nav_mode, "sheet": "FINAL_FILTER_RECHECK", "row": None, "switch": sw2, "cand": str(c2), "label": "FINAL_RECHECK", "fn": "tools.opt.v12_pilot.evaluate_prepared_sanitized", "window_days": args.window_days, "gain_pct": g, "trades": (res or {}).get("trades"), "valid": (res or {}).get("valid"), "invalid_reason": (res or {}).get("invalid_reason"), "cum_before": cum0, "delta": d, "secs": None, "cached": cached, "err": err})
            if ok and d > 1e-9 and not promotion_block_reason(sw2) and (best is None or d > best[0]) and not (_v17_on and (tim_guard_veto((res or {}).get("tim_pct"), chain_tim) or trades_guard_veto((res or {}).get("trades"), chain_trades))):
                best = (d, sw2, c2, g)  # V17: FFR obeys the same TIM/trades chain-health guards (canary RLC D: FFR pushed TIM 20+ -> 9.3 -> compliance REDO)
        if best is not None:
            d, sw2, c2, g = best
            cumulative_gain = float(g)
            cumulative_overrides.update(_switch_overrides(sw2, _parse_opt_value(c2, defaults.get(sw2))))
            cumulative_overrides, _ = sanitize_overrides(cumulative_overrides, defaults)
            _bs_note("FINAL_RECHECK", cumulative_overrides, (results.get((sw2, c2)) or (None,))[0])
            for rec in recs:
                if rec[0] == sw2 and rec[1] == c2:
                    rec[6] = True
        recs.sort(key=lambda x: (x[5] is None, -(x[5] or 0)))
        for i, rec in enumerate(recs, 2):
            for j, val in enumerate(rec, 1):
                c = fws.cell(row=i, column=j, value=val)
                c.font = Font(name="Arial", size=10, bold=(j == 7 and bool(rec[6])))
            dcell = fws.cell(row=i, column=6)
            if isinstance(rec[5], (int, float)):
                dcell.font = Font(name="Arial", size=10, color="006100" if rec[5] > 1e-9 else "9C0006")
        progress["final_filter_recheck"] = {"cumulative_before": cum0, "cumulative_after": float(cumulative_gain), "n": len(recs), "promoted": [best[1], best[2], best[0]] if best else None, "deltas": {f"{r[0]}={r[1]}": r[5] for r in recs}}
        progress["cumulative_gain"] = float(cumulative_gain)
        progress["cumulative_overrides"] = dict(cumulative_overrides)
        print(f"[final-recheck] {len(recs)} distinct orange filters vs final cum {cum0:.4f} computed={len(futs)} cached={len(recs)-len(futs)} best={'%s=%s %+.4f' % (best[1], best[2], best[0]) if best else 'none'} -> cum {cumulative_gain:.4f} ({_t.time()-t0:.1f}s)", flush=True)
    def _bs_note(stage, ov, res):
        # USER 2026-10-13 BEST-SEEN: best fresh-verified (guard-passing) set of this board -> progress["best_seen"]; the publish
        # gate falls back to it so a published final is never below a set this board already verified. Never raises.
        try:
            try:
                _npz_bs = str(_run_npz_short)
            except NameError:
                _npz_bs = ""
            # USER 2026-10-13 ABSOLUTE best-start law: the publish floor records every engine-valid set above the trade floor;
            # the TIM band guards promotions during the fill, it is never a reason to publish a LOWER result
            progress["best_seen"] = _endgame_best_seen_note(progress.get("best_seen"), stage, sanitize_overrides(dict(ov), defaults)[0], res, _npz_bs, ADAPT_FLOOR_TRADES, (-1e18, 1e18))
        except Exception as _bse:
            print(f"[BEST-SEEN-warn] {new_symside} {stage}: {_bse}", flush=True)
    def _endgame_filter_cycle():
        # USER 2026-10-07 ENDGAME (authoritative order): filter DEFAULTS (last-best) apply from moment 1 (running set);
        # filter ALTERNATIVES are tested per-row after the switch (orange). At workbook end, BEFORE diagnose+repair:
        #   1. REPAIR illegal values (int-truncate float count knobs, drop ABLATION_DISABLE_*=True P0 §64) + fresh re-eval.
        #   2. STRIP all promoted filters -> naked switch-only base + fresh re-eval.
        #   3. NAKED RETEST every promoted switch leave-one-out vs the stripped base: each shows its ACTUAL marginal
        #      delta. Honest zeros are cause-tagged (§18 protocol: fp-same=NON_BINDING, fp-moved=OFFSET) — never faked (§19).
        #   4. REAPPLY filters one-by-one greedy (best positive first) toward gain > bh+10pts. Greedy law §14.2 rules the
        #      method (ALL positives reapply, even past the target); the target is a reported goal, never forced.
        # Dropped (never-positive) filters are _c_drop-ped from their original C cells so C == the final set (§56.0).
        # TIER-entry share is measured from the final ledger and reported (flag only — no auto-action).
        # Self-improvement (USER 2026-10-07): NAKED/REAPPLY try-order follows cross-workbook EV (endgame_knowledge.json);
        # every run appends endgame_ledger.jsonl + merges stats. No look-ahead: knowledge loads at entry, appends at exit.
        # Greedy adoption is UNCHANGED (§14.2 — order only affects which positives land first under a binding budget).
        # Resume-safe (progress endgame result_key), budgeted (herd 90-min cap), V15_ENDGAME=0 disables. Never raises.
        nonlocal cumulative_gain, cumulative_overrides
        import hashlib as _eg_hl
        t0 = _t.time()
        try:
            if os.environ.get("V15_ENDGAME", "1") != "1":
                print(f"[ENDGAME] {new_symside} skipped (V15_ENDGAME=0)", flush=True)
                progress["endgame"] = {"skipped": "V15_ENDGAME=0"}
                return
            if fast_switches is not None or prepared is None:
                print(f"[ENDGAME] {new_symside} skipped (fast mode or no prepared NPZ)", flush=True)
                progress["endgame"] = {"skipped": "fast/no-prepared"}
                return
            budget = min(float(os.environ.get("V15_ENDGAME_S", "600")), 5400.0 - (t0 - _PILOT_T0) - 900.0)
            if budget < 60:
                print(f"[ENDGAME] {new_symside} skipped: only {budget:.0f}s left inside the 90-min herd cap", flush=True)
                progress["endgame"] = {"skipped": f"budget {budget:.0f}s"}
                return
            max_evals = int(os.environ.get("V15_ENDGAME_MAX_EVALS", "1500"))
            target_pts = float(os.environ.get("V15_ENDGAME_TARGET_PTS", "10.0"))
            _sk = lambda ov: _eg_hl.md5(json.dumps(sorted((k, str(v)) for k, v in ov.items())).encode()).hexdigest()
            prev = progress.get("endgame") or {}
            if prev.get("complete") and prev.get("result_key") == _sk(cumulative_overrides):
                print(f"[ENDGAME] {new_symside} already ran on this exact set — skip (resume)", flush=True)
                return
            _eg_entry_gain = float(cumulative_gain)
            _eg_ev_on = os.environ.get("V15_ENDGAME_EV_ORDER", "1") == "1"
            _eg_ledger_on = os.environ.get("V15_ENDGAME_LEDGER", "1") == "1"
            _eg_know, _eg_know_n = {}, 0
            _eg_rank_know, _eg_know_src = {}, "none"
            if _eg_ev_on or _eg_ledger_on:
                try:
                    _eg_kp = PROGRESS_DIR / "endgame_knowledge.json"
                    if _eg_kp.exists():
                        _eg_know = json.loads(_eg_kp.read_text()) or {}
                        _eg_know_n = int((_eg_know.get("workbooks") or {}).get("n", 0))
                except Exception as _kerr:
                    print(f"[ENDGAME-warn] {new_symside} knowledge load failed ({_kerr}) — alphabetical order", flush=True)
                    _eg_know, _eg_know_n = {}, 0
                _eg_rank_know, _eg_know_src = _eg_know, "campaign"
                # USER 2026-10-13: fleet-wide knowledge first (tools/v15_endgame_knowledge_merge.py, all hosts x all campaigns),
                # per-campaign file is the fallback + the local write target. V15_ENDGAME_KNOWLEDGE overrides the fleet path.
                try:
                    _eg_fp = Path(os.environ.get("V15_ENDGAME_KNOWLEDGE") or (ROOT / "data" / "endgame" / "endgame_knowledge_fleet.json"))
                    if _eg_fp.exists():
                        _eg_fleet = json.loads(_eg_fp.read_text()) or {}
                        _eg_fn = int((_eg_fleet.get("workbooks") or {}).get("n", 0))
                        if _eg_fn > 0:
                            _eg_rank_know, _eg_know_n, _eg_know_src = _endgame_fleet_view(_eg_fleet, map_key_for_symside(new_symside)), _eg_fn, "fleet"
                except Exception as _kferr:
                    print(f"[ENDGAME-warn] {new_symside} fleet knowledge load failed ({_kferr}) — campaign knowledge", flush=True)
            if _eg_know_n:
                print(f"[ENDGAME] {new_symside} EV-order from {_eg_know_n} prior workbooks ({_eg_know_src}, ev_on={_eg_ev_on})", flush=True)
            deadline = t0 + budget
            _n_eval = [0]
            def _eg_eval(label, ov, cum_before, switch="", cand=""):
                _n_eval[0] += 1
                dl = min(deadline, _t.time() + YELLOW_TIMEOUT * 4)
                return _get("ENDGAME", None, switch, cand, label, sanitize_overrides(dict(ov), defaults)[0], dl, float(cum_before))
            # 1. partition promoted keys into switches vs filters (orange-row switches + yellow header names)
            filt_names = set()
            try:
                for sname in tabs:
                    for (rr, sw, _cd) in per_tab_rows.get(sname, []):
                        if (sname, rr) in orange_rows:
                            filt_names.add(sw)
                    for hdr in header_maps.get(sname, {}):
                        filt_names.add(str(hdr).split("=", 1)[0].strip())
            except Exception:
                pass
            F = {k: v for k, v in cumulative_overrides.items() if k in filt_names and not _same_val(v, defaults.get(k))}
            S = {k: v for k, v in cumulative_overrides.items() if k not in filt_names and not _same_val(v, defaults.get(k))}
            print(f"[ENDGAME] {new_symside} start: {len(S)} switches, {len(F)} filters, target bh+{target_pts:g} (bh={bh})", flush=True)
            # 2. REPAIR illegal values (encyclopedia duty): int-truncate float counts, drop ablation-True P0
            repaired, repairs = dict(cumulative_overrides), []
            for k in list(repaired.keys()):
                if k.startswith("ABLATION_DISABLE_") and bool(repaired[k]):
                    repairs.append((k, repaired.pop(k), "<DROPPED-P0>"))
            for k, v in list(repaired.items()):
                dv = defaults.get(k)
                if isinstance(dv, int) and not isinstance(dv, bool) and isinstance(v, float) and not v.is_integer():
                    repaired[k] = int(v)
                    repairs.append((k, v, int(v)))
            _eg_ref_res = None
            if repairs:
                rres, rerr = _eg_eval("ENDGAME_REPAIR", repaired, float(cumulative_gain), "REPAIR", f"{len(repairs)}fixes")
                # USER 2026-10-13: int-truncation lost gain (run31/32 REPAIR sum -205.4pp s2/s5/s6) — also try the ceil variant
                # (a `>= 2.5` count gate behaves like 3, not 2) and keep the better legal set (fresh evals, NO-LIES).
                _ceil = dict(repaired)
                _n_ceil = 0
                for k, a, b in repairs:
                    if isinstance(b, int) and isinstance(a, float) and k in _ceil:
                        _ceil[k] = int(b) + (1 if a > b else -1 if a < b else 0)
                        _n_ceil += 1
                if _n_ceil:
                    cres_, cerr_ = _eg_eval("ENDGAME_REPAIR", _ceil, float(cumulative_gain), "REPAIR_CEIL", f"{_n_ceil}ceil")
                    if cres_ is not None and cres_.get("gain_pct") is not None and bool(cres_.get("valid")) and (rres is None or rres.get("gain_pct") is None or float(cres_["gain_pct"]) > float(rres["gain_pct"]) + 1e-9):
                        print(f"[ENDGAME] {new_symside} REPAIR ceil variant beats floor ({(rres or {}).get('gain_pct')} -> {float(cres_['gain_pct']):.4f})", flush=True)
                        repaired, rres, rerr = _ceil, cres_, cerr_
                        repairs = [(k, a, (repaired.get(k) if isinstance(b, int) else b)) for k, a, b in repairs]
                if rres is not None and rres.get("gain_pct") is not None:
                    print(f"[ENDGAME] {new_symside} REPAIR adopted ({len(repairs)} fixes): {float(cumulative_gain):.4f} -> {float(rres['gain_pct']):.4f} ({rerr or 'ok'})", flush=True)
                    cumulative_overrides = sanitize_overrides(repaired, defaults)[0]
                    cumulative_gain = float(rres["gain_pct"])
                    F = {k: v for k, v in cumulative_overrides.items() if k in filt_names and not _same_val(v, defaults.get(k))}
                    S = {k: v for k, v in cumulative_overrides.items() if k not in filt_names and not _same_val(v, defaults.get(k))}
                    _eg_ref_res = rres
                else:
                    print(f"[ENDGAME] {new_symside} REPAIR eval failed ({rerr}) — set unchanged, fixes logged only", flush=True)
            if _eg_ref_res is None:
                # NO-LIES reference: fresh eval of exactly the (legal) entry set — the ADOPT guard compares against this
                _eres, _eerr = _eg_eval("ENDGAME_ENTRY", cumulative_overrides, float(cumulative_gain), "ENTRY", "fresh")
                if _eres is not None and _eres.get("gain_pct") is not None:
                    _eg_ref_res = _eres
                    if abs(float(_eres["gain_pct"]) - float(cumulative_gain)) > 1e-6:
                        print(f"[ENDGAME] {new_symside} entry fresh {float(_eres['gain_pct']):.4f} != recorded cum {float(cumulative_gain):.4f} — fresh is the guard reference", flush=True)
            _eg_ref_gain = float(_eg_ref_res["gain_pct"]) if _eg_ref_res is not None else float(cumulative_gain)
            _eg_legal = (not repairs) or (_eg_ref_res is not None and _eg_ref_res is rres)
            if _eg_ref_res is not None and _eg_legal:
                _bs_note("ENDGAME_ENTRY", cumulative_overrides, _eg_ref_res)
            # 3. STRIP filters -> naked switch-only base
            _pre_strip_gain = float(cumulative_gain)
            stripped = {k: v for k, v in cumulative_overrides.items() if k not in F}
            sres, serr = _eg_eval("ENDGAME_STRIP", stripped, float(cumulative_gain), "STRIP", f"{len(F)}filters")
            if sres is None or sres.get("gain_pct") is None:
                print(f"[ENDGAME] {new_symside} STRIP eval failed ({serr}) — abort, set unchanged", flush=True)
                progress["endgame"] = {"skipped": f"strip eval {serr}", "repairs": [(k, str(a), str(b)) for k, a, b in repairs]}
                return
            base_gain = float(sres["gain_pct"])
            base_fp = str((sres or {}).get("behavior_fingerprint") or "")
            base = sanitize_overrides(stripped, defaults)[0]
            print(f"[ENDGAME] {new_symside} STRIP: {float(cumulative_gain):.4f} -> naked {base_gain:.4f} ({len(F)} filters out)", flush=True)
            # 4. NAKED RETEST each promoted switch leave-one-out vs the stripped base (ACTUAL marginal deltas)
            naked_rows = []
            for k in _endgame_rank(list(S.keys()), _eg_rank_know, _eg_ev_on):
                if _t.time() > deadline or _n_eval[0] >= max_evals or _SHUTDOWN["v"]:
                    naked_rows.append((k, S[k], None, "BUDGET/SHUTDOWN"))
                    continue
                wo = {kk: vv for kk, vv in base.items() if kk != k}
                wres, werr = _eg_eval("ENDGAME_NAKED", wo, base_gain, k, str(S[k]))
                if wres is None or wres.get("gain_pct") is None:
                    naked_rows.append((k, S[k], None, f"EVAL_{werr}"))
                    continue
                d = base_gain - float(wres["gain_pct"])
                cause = ""
                if abs(d) < 1e-9:
                    wfp = str((wres or {}).get("behavior_fingerprint") or "")
                    cause = "NON_BINDING_ZERO" if wfp == base_fp else "OFFSET_ZERO"
                naked_rows.append((k, S[k], d, cause, int(wres.get("trades") or 0), bool(wres.get("valid"))))
            n_zero = sum(1 for r in naked_rows if r[2] is not None and abs(r[2]) < 1e-9)
            print(f"[ENDGAME] {new_symside} NAKED: {len(naked_rows)} switches retested, {n_zero} honest-zero ({[(r[0], r[3]) for r in naked_rows if r[2] is not None and abs(r[2]) < 1e-9][:8]})", flush=True)
            # 5. REAPPLY filters one-by-one greedy toward bh+target
            working, work_gain = dict(base), base_gain
            remaining = dict(F)
            applied, target_step = [], None
            tgt = (float(bh) + target_pts) if bh is not None else None
            while remaining and _t.time() < deadline and _n_eval[0] < max_evals and not _SHUTDOWN["v"]:
                best_f, best_g, best_res = None, None, None
                for fk in _endgame_rank(list(remaining.keys()), _eg_rank_know, _eg_ev_on):
                    fv = remaining[fk]
                    if _t.time() > deadline or _n_eval[0] >= max_evals:
                        break
                    cand_ov = dict(working)
                    cand_ov[fk] = fv
                    cres, cerr = _eg_eval("ENDGAME_REAPPLY_TRY", cand_ov, work_gain, fk, str(fv))
                    if cres is None or cres.get("gain_pct") is None:
                        continue
                    g = float(cres["gain_pct"])
                    if g - work_gain > 1e-9 and (best_g is None or g > best_g):
                        best_f, best_g, best_res = fk, g, cres
                if best_f is None:
                    break
                working[best_f] = remaining.pop(best_f)
                work_gain = best_g
                applied.append((best_f, working[best_f], best_g, int((best_res or {}).get("trades") or 0)))
                if tgt is not None and target_step is None and best_g >= tgt:
                    target_step = len(applied)
            target_met = tgt is not None and work_gain >= tgt
            print(f"[ENDGAME] {new_symside} REAPPLY: {len(applied)}/{len(F)} filters back, {base_gain:.4f} -> {work_gain:.4f}, target {('MET@step%d' % target_step) if target_step else ('MISSED' if tgt is not None else 'n/a')} (bh+{target_pts:g}={tgt})", flush=True)
            # 6. ADOPT the reapplied set (fresh NO-LIES eval of exactly the adopted set) + C-reconcile drops
            # USER 2026-10-13 ADOPT GUARD: the STRIP base is discovery only (never adopted); the reapplied set replaces the
            # entry set ONLY when its fresh eval is valid + trades floor + TIM band and gain >= the fresh legal entry gain.
            # Otherwise the entry set stays unchanged ([ENDGAME-REJECT]). V15_ENDGAME_ADOPT_GUARD=0 restores the old rule.
            adopted = False
            _eg_reject = ""
            ares, aerr = _eg_eval("ENDGAME_ADOPT", working, base_gain, "ADOPT", f"{len(applied)}filters")
            _eg_cand_gain = float(ares["gain_pct"]) if (ares is not None and ares.get("gain_pct") is not None) else None
            if os.environ.get("V15_ENDGAME_ADOPT_GUARD", "1") == "1":
                _eg_ok, _eg_why = _endgame_adopt_verdict(ares, _eg_ref_gain, (_eg_ref_res or {}).get("tim_pct"), (_eg_ref_res or {}).get("trades"), ADAPT_FLOOR_TRADES, (QUAL_TIM_MIN, QUAL_TIM_MAX))
            else:
                _eg_ok, _eg_why = bool(ares is not None and ares.get("gain_pct") is not None and int(ares.get("trades") or 0) > 0 and ares.get("valid")), "guard-off"
            if not _eg_ok and _eg_cand_gain is not None:
                _eg_reject = _eg_why
                print(f"[ENDGAME-REJECT] {new_symside} lift {(_eg_cand_gain - _eg_ref_gain):+.4f} (entry {_eg_ref_gain:.4f} -> candidate {_eg_cand_gain:.4f} trades={(ares or {}).get('trades')} tim={(ares or {}).get('tim_pct')}) {_eg_why} — entry set kept", flush=True)
            if _eg_ok and ares is not None:
                _bs_note("ENDGAME_ADOPT", working, ares)
            if _eg_ok:
                cumulative_overrides = sanitize_overrides(working, defaults)[0]
                cumulative_gain = float(ares["gain_pct"])
                progress["cumulative_overrides"] = dict(cumulative_overrides)
                progress["cumulative_gain"] = float(cumulative_gain)
                adopted = True
                for dk in remaining.keys():
                    try:
                        if dk in _c_where:
                            _c_drop(*_c_where.pop(dk), dk)
                    except Exception:
                        pass
                if remaining:
                    print(f"[ENDGAME] {new_symside} C-reconciled: {len(remaining)} never-positive filters dropped from C: {sorted(remaining.keys())[:10]}", flush=True)
            else:
                print(f"[ENDGAME] {new_symside} ADOPT refused (valid={bool((ares or {}).get('valid'))} trades={(ares or {}).get('trades')} err={aerr or _eg_why}) — set unchanged", flush=True)
            _eg_lift = float(cumulative_gain) - _eg_entry_gain
            _eg_cand_lift = (_eg_cand_gain - _eg_entry_gain) if _eg_cand_gain is not None else None
            # 7. TIER-entry share from the final ledger (report-only flag; no auto-action)
            tier_share, tier_n, open_n = None, 0, 0
            try:
                from tools.opt import v12_pilot as _vp_eg
                _lres = _vp_eg.evaluate_prepared_sanitized(prepared, dict(cumulative_overrides), args.window_days, True)
                for _lt in ((_lres or {}).get("ledger") or []):
                    if str((_lt or {}).get("type") or "").upper() != "OPEN":
                        continue
                    open_n += 1
                    if str((_lt or {}).get("reason") or (_lt or {}).get("entry_reason") or "").upper().startswith(("TIER1", "TIER2")):
                        tier_n += 1
                tier_share = (tier_n / open_n) if open_n else 0.0
            except Exception as _te:
                print(f"[ENDGAME-warn] {new_symside} tier-share ledger eval: {_te}", flush=True)
            # 8. ENDGAME sheet + progress record (resume key = adopted set)
            try:
                if "ENDGAME_FILTER_CYCLE" in wb.sheetnames:
                    del wb["ENDGAME_FILTER_CYCLE"]
                ews = wb.create_sheet("ENDGAME_FILTER_CYCLE")
                B = Font(name="Arial", size=10, bold=True)
                def _erow(vals, bold=False):
                    ews.append(list(vals))
                    if bold:
                        for cc in ews[ews.max_row]:
                            cc.font = B
                _erow(["ENDGAME_FILTER_CYCLE", new_symside, f"switches={len(S)}", f"filters={len(F)}", f"target=bh+{target_pts:g}={tgt}", f"target_met={target_met}", f"adopted={adopted}", f"evals={_n_eval[0]}", f"secs={round(_t.time()-t0,1)}"], True)
                _erow(["REPAIR", "key", "before", "after"], True)
                for k, a, b in repairs:
                    _erow(["REPAIR", k, str(a)[:60], str(b)[:60]])
                _erow(["STRIP", f"{len(F)} filters out", f"{_pre_strip_gain:.4f}->{base_gain:.4f}", "base=sanitized switch-only set"])
                _erow(["NAKED_RETEST", "switch", "value", "marginal_delta_vs_stripped_base", "cause_if_zero", "trades_wo", "valid_wo"], True)
                for r in naked_rows:
                    _erow(["NAKED", r[0], str(r[1])[:40], r[2], r[3] if len(r) > 3 else "", r[4] if len(r) > 4 else "", r[5] if len(r) > 5 else ""])
                _erow(["REAPPLY", "step", "filter", "value", "gain_after", "trades"], True)
                for i, (fk, fv, g, tr) in enumerate(applied, 1):
                    _erow(["REAPPLY", i, fk, str(fv)[:40], g, tr])
                _erow(["DROPPED_FILTERS", ",".join(sorted(remaining.keys()))[:900]])
                _erow(["TIER_SHARE", f"{tier_n}/{open_n}={tier_share}", "DOMINANT>30%" if (tier_share or 0) > 0.30 else "ok", "report-only: no auto-action"])
                _erow(["KNOWLEDGE", f"prior_workbooks={_eg_know_n}", f"ev_order={bool(_eg_ev_on)}", f"entry={_eg_entry_gain:.4f}", f"lift={_eg_lift:+.4f}", f"source={_eg_know_src}"])
                _erow(["ADOPT_GUARD", f"ref={_eg_ref_gain:.4f}", f"candidate={_eg_cand_gain}", f"adopted={adopted}", f"reject={_eg_reject or '-'}"])
            except Exception as _ese:
                print(f"[ENDGAME-warn] {new_symside} sheet write: {_ese}", flush=True)
            progress["endgame"] = {"complete": True, "result_key": _sk(dict(cumulative_overrides)), "switches": len(S), "filters": len(F),
                                   "repairs": [(k, str(a), str(b)) for k, a, b in repairs], "strip_gain": base_gain,
                                   "naked": [(r[0], r[2], r[3] if len(r) > 3 else "") for r in naked_rows],
                                   "reapplied": [(f, g) for f, _v, g, _t in applied], "dropped": sorted(remaining.keys()),
                                   "target_pts": target_pts, "target_gain": tgt, "target_met": target_met, "target_step": target_step,
                                   "adopted": adopted, "final_gain": float(cumulative_gain), "tier_share": tier_share,
                                   "ref_gain": _eg_ref_gain, "cand_gain": _eg_cand_gain, "rejected": _eg_reject, "knowledge_src": _eg_know_src,
                                   "tier_opens": tier_n, "opens": open_n, "evals": _n_eval[0], "secs": round(_t.time() - t0, 1)}
            try:
                _atomic_write_json(progress_path, progress)
            except Exception:
                pass
            if _eg_ledger_on:
                try:
                    _rec_key = f"{new_symside}|{_sk(dict(cumulative_overrides))}"
                    _eg_lp = PROGRESS_DIR / "endgame_ledger.jsonl"
                    _seen = False
                    if _eg_lp.exists():
                        try:
                            with open(_eg_lp) as _lf:
                                for _ln in _lf:
                                    if _rec_key in _ln[:220]:
                                        _seen = True
                                        break
                        except Exception:
                            pass
                    if not _seen:
                        _step_prev = base_gain
                        _seq = []
                        for _fk, _fv, _g, _tr in applied:
                            _seq.append({"filter": _fk, "step_delta": round(float(_g) - float(_step_prev), 6), "gain_after": float(_g), "trades": _tr})
                            _step_prev = _g
                        _rec = {"symside": new_symside, "ts": datetime.datetime.now(datetime.timezone.utc).isoformat(), "key": _rec_key, "ev_order": bool(_eg_ev_on), "know_n": _eg_know_n, "entry_gain": _eg_entry_gain, "strip_gain": base_gain, "final_gain": float(cumulative_gain), "lift": _eg_lift, "adopted": adopted, "target_met": target_met,
                                "naked": [{"switch": r[0], "value": str(r[1])[:60], "delta": r[2], "cause": r[3] if len(r) > 3 else ""} for r in naked_rows],
                                "reapply_seq": _seq, "dropped": sorted(remaining.keys()), "tier_share": tier_share, "evals": _n_eval[0],
                                "cat_side": map_key_for_symside(new_symside), "ref_gain": _eg_ref_gain, "cand_gain": _eg_cand_gain, "cand_lift": _eg_cand_lift, "rejected": _eg_reject}
                        with open(_eg_lp, "a") as _lf:
                            _lf.write(json.dumps(_rec) + "\n")
                        _naked_items = []
                        for r in naked_rows:
                            _naked_items.append((r[0], r[2]))
                            _naked_items.append((f"{r[0]}={str(r[1])[:60]}", r[2]))
                        _endgame_merge_knowledge(_eg_know, _naked_items, [(_s["filter"], _s["step_delta"]) for _s in _seq], list(remaining.keys()), _eg_lift, target_met, adopted, _eg_cand_lift, bool(_eg_reject))
                        _atomic_write_json(PROGRESS_DIR / "endgame_knowledge.json", _eg_know)
                        _wb = _eg_know.get("workbooks") or {}
                        _ml = (float(_wb.get("sum_lift", 0.0)) / _wb["n"]) if _wb.get("n") else 0.0
                        print(f"[ENDGAME-PROOF] {new_symside} lift {_eg_lift:+.4f} (entry {_eg_entry_gain:.4f} -> final {float(cumulative_gain):.4f}); aggregate n={_wb.get('n', 0)} mean_lift={_ml:+.4f} P(lift>0)={_wb.get('pos_lift', 0)}/{_wb.get('n', 0)} targets={_wb.get('target_met', 0)} adopted={_wb.get('adopted', 0)} rejected={_wb.get('rejected', 0)} cand_lift={(_eg_cand_lift if _eg_cand_lift is not None else float('nan')):+.4f}", flush=True)
                except Exception as _le:
                    print(f"[ENDGAME-warn] {new_symside} ledger/knowledge write: {_le}", flush=True)
            print(f"[ENDGAME] {new_symside} done in {round(_t.time()-t0,1)}s, {target_met=}, adopted={adopted}", flush=True)
        except V15Shutdown:
            raise
        except Exception as _ege:
            import traceback as _tb_eg
            print(f"[ENDGAME-warn] {new_symside}: {_ege}\n{_tb_eg.format_exc()[-1200:]}", flush=True)

    def _diagnose_repair():
        # USER 2026-10-06: post-fill DIAGNOSE+REPAIR (tools/v15_diagnose_repair.run) — see the call site for the contract.
        nonlocal cumulative_gain, cumulative_overrides
        import hashlib as _hl
        from tools import v15_diagnose_repair as _DR
        from tools.opt import v12_pilot as _vp
        t0 = _t.time()
        mode = os.environ.get("V15_DIAG_REPAIR_MODE", "publish")
        budget = float(os.environ.get("V15_DIAG_REPAIR_S", "900"))
        hard_left = 5400.0 - (t0 - _PILOT_T0) - 900.0  # herd kills pilots >90 min; keep 15 min for DONE/publish/365D
        budget = min(budget, hard_left)
        _sk = lambda ov: _hl.md5(json.dumps(sorted((k, str(v)) for k, v in ov.items())).encode()).hexdigest()
        prev = progress.get("diagnose_repair") or {}
        if prev.get("complete") and prev.get("result_key") == _sk(cumulative_overrides):
            print(f"[DIAG] {new_symside} already repaired this exact set ({prev.get('accepted')}) — skip (resume)", flush=True)
            return
        if budget < 120:
            print(f"[DIAG] {new_symside} skipped: only {budget:.0f}s left inside the 90-min herd cap", flush=True)
            progress["diagnose_repair"] = {"skipped": f"budget {budget:.0f}s"}
            return
        # candidates = every evaluable template row (white + orange) + every yellow filter=opt, distinct
        cands, seen = [], set()
        for sname in tabs:
            for (rr, sw, cand) in per_tab_rows.get(sname, []):
                if (sw, str(cand)) in seen:
                    continue
                try:
                    st = _row_static(sname, rr, sw, cand)
                except Exception:
                    continue
                if st.get("kind") != "eval":
                    continue
                ov = _switch_overrides(sw, _parse_opt_value(cand, defaults.get(sw)))
                if not ov:
                    continue
                seen.add((sw, str(cand)))
                cands.append({"tab": sname, "row": rr, "switch": sw, "cand": cand, "ov": ov, "orange": (sname, rr) in orange_rows, "blocked": promotion_block_reason(sw, sname)})
        for sname in tabs:
            for hdr in header_maps.get(sname, {}):
                filt, opt = [x.strip() for x in hdr.split("=", 1)]
                if (filt, opt) in seen or filt not in known_config_fields() or filt in UNWIRED_FILTERS or filt in UNWIRED_SWITCHES:
                    continue
                val = _parse_opt_value(opt, defaults.get(filt))
                if not _cand_compatible(filt, val, defaults)[0]:
                    continue
                seen.add((filt, opt))
                cands.append({"tab": sname, "row": None, "switch": filt, "cand": opt, "ov": {filt: val}, "orange": True, "blocked": promotion_block_reason(filt, sname)})
        def _eval_many(items, phase, cum_before, deadline):
            cb = float(cum_before) if cum_before is not None else float(cumulative_gain)
            for _l, ov, _c in items:
                _submit(ov)
            wave_deadline = min(deadline + 60.0, _t.time() + YELLOW_TIMEOUT * (-(-len(items) // max(1, _n_proc)) + 2))
            out = []
            for lab, ov, c in items:
                res, err = _get("DIAGNOSE_REPAIR", (c or {}).get("row"), (c or {}).get("switch", lab), (c or {}).get("cand", ""), f"{phase}:{lab}", ov, wave_deadline, cb)
                out.append((None if err else res, err))
            _harvest()
            return out
        def _eval_ledger(ov):
            ex = _cf.ThreadPoolExecutor(max_workers=1)
            try:
                return ex.submit(_vp.evaluate_prepared_sanitized, prepared, dict(ov), args.window_days, True).result(timeout=90)
            except Exception as _le:
                print(f"[DIAG-warn] ledger eval: {_le}", flush=True)
                return None
            finally:
                ex.shutdown(wait=False)
        _span = {"v": None, "done": False}
        def _ensure_365prep():
            if not _span["done"]:
                _span["v"], _span["done"] = _npz_span_days(new_symside), True
                try:  # USER 2026-10-06: the 365D slice is prepared ONCE and kept in RAM for every finalist
                    _span["prep"] = _vp.prepare_batch(new_symside, 365)
                    print(f"[DIAG] {new_symside} 365D slice prepared in RAM (span {_span['v']})", flush=True)
                except Exception as _pe365:
                    _span["prep"] = None
                    print(f"[DIAG-warn] 365D prepare failed ({_pe365}) — disk path per finalist", flush=True)
        def _eval_many_365(items365, deadline):
            # USER 2026-10-07: batched 365D dual-window scoring (was serial 1.5s x N) — same evaluator, same values
            if os.environ.get("V15_SKIP_365D_AT_DONE") == "1" or not items365:
                return [(None, None)] * len(items365)
            _ensure_365prep()
            if _SHUTDOWN["v"]:
                raise V15Shutdown("shutdown before 365D batch")
            pairs365 = [(it if isinstance(it, (tuple, list)) else (it, None)) for it in items365]  # USER 2026-10-07: prefetch sends (ov,key) pairs, graph_search sends bare ovs — accept both
            _dl = min(deadline, _t.time() + max(60.0, 200.0 * (-(-len(pairs365) // 6) + 1)))
            out365 = [(None, None)] * len(pairs365)
            if _span.get("prep") is not None:
                ex365 = _cf.ThreadPoolExecutor(max_workers=min(6, len(pairs365)))
                try:
                    futs = [ex365.submit(_vp.evaluate_prepared_sanitized, _span["prep"], dict(ov), 365) for ov, _k in pairs365]
                    for _i, _f in enumerate(futs):
                        try: out365[_i] = (_f.result(timeout=max(1.0, _dl - _t.time())), _span["v"])
                        except Exception: out365[_i] = (None, _span["v"])
                        if _SHUTDOWN["v"]:
                            raise V15Shutdown("shutdown in 365D batch")
                finally:
                    try: ex365.shutdown(wait=False, cancel_futures=True)
                    except Exception: pass
            else:
                for _i, (ov, _k) in enumerate(pairs365):
                    if _SHUTDOWN["v"]:
                        raise V15Shutdown("shutdown in 365D batch")
                    if _t.time() > _dl:
                        break
                    try: out365[_i] = (_vp.evaluate_sanitized_with_timeout(new_symside, dict(ov), 365, timeout_sec=180), _span["v"])
                    except Exception: pass
            return out365
        _last_diag_ckpt = {"t": 0.0}
        def _diag_ckpt(delta):
            # USER 2026-10-07: merge diagnose memo deltas + persist (throttled) — resume replays, never recomputes
            try:
                if delta.get("memo"): progress.setdefault("diagnose_memo", {}).update(delta["memo"])
                if delta.get("m365"): progress.setdefault("diagnose_m365", {}).update(delta["m365"])
                if delta.get("autopsy"): progress["diagnose_autopsy"] = delta["autopsy"]
                if delta.get("gs"): progress["diagnose_gs"] = delta["gs"]
                progress["diagnose_npz"] = _run_npz_short
                if _t.time() - _last_diag_ckpt["t"] >= (_flush_interval_s("V15_PROGRESS_JSON_EVERY_S", PROGRESS_JSON_EVERY_S) if _v18_io else 10.0):
                    _last_diag_ckpt["t"] = _t.time()
                    _atomic_write_json(progress_path, progress)
            except V15Shutdown: raise
            except Exception: pass
        def _eval_365(ov):
            if os.environ.get("V15_SKIP_365D_AT_DONE") == "1":
                return None, None
            _ensure_365prep()
            r = None
            ex = _cf.ThreadPoolExecutor(max_workers=1)
            try:
                if _span.get("prep") is not None:
                    r = ex.submit(_vp.evaluate_prepared_sanitized, _span["prep"], dict(ov), 365).result(timeout=180)
                else:
                    r = _vp.evaluate_sanitized_with_timeout(new_symside, dict(ov), 365, timeout_sec=int(min(QUAL_365D_TIMEOUT, 180)))
            except Exception as _e365:
                print(f"[DIAG-warn] 365D eval: {_e365}", flush=True)
            finally:
                ex.shutdown(wait=False)
            _delta_log({"ts": utcnow(), "sym_side": new_symside, "nav": "sequential", "sheet": "DIAGNOSE_REPAIR", "row": None, "switch": "VERIFY_365D", "cand": "", "label": "DIAG_365D", "fn": "tools.opt.v12_pilot.evaluate_sanitized", "window_days": 365, "gain_pct": (r or {}).get("gain_pct"), "trades": (r or {}).get("trades"), "tim": (r or {}).get("tim_pct"), "valid": (r or {}).get("valid"), "invalid_reason": (r or {}).get("invalid_reason")})
            return r, _span["v"]
        def _eval_many_ledger(items, phase, cum_before, deadline):
            # trade autopsy screen: ledger evals on the same fork pool (NPZ in RAM); one delta-log line per eval (sentinel)
            cb = float(cum_before) if cum_before is not None else float(cumulative_gain)
            futs = []
            for lab, ov, c in items:
                futs.append((lab, ov, c, _pool.submit(_pool_eval_ledger, ov, args.window_days) if _pool is not None else None, _t.time()))
            wave_deadline = min(deadline + 60.0, _t.time() + YELLOW_TIMEOUT * (-(-len(items) // max(1, _n_proc)) + 2))
            out = []
            for lab, ov, c, fut, t0e in futs:
                res, err = None, ""
                try:
                    if fut is not None:
                        res, _secs = fut.result(timeout=max(0.01, wave_deadline - _t.time()))
                    else:
                        res, _secs = _pool_eval_ledger(ov, args.window_days)
                except Exception as _le:
                    err = f"ERR {_le}"[:120]
                    if fut is not None:
                        fut.cancel()
                g = (res or {}).get("gain_pct")
