    _v18_prof_on = bool(_V18P is not None and _V18P.profile_on())
    _v18_prof, _v18_prof_rows, _v18_prof_min_n, _v18_prof_why = (_V18P.load_profile(_v18_floor_cs, ROOT) if _v18_prof_on else (None, None, None, "off"))
    _v18_prof_tot = {"rows": 0, "rows_dead": 0, "cells_pool": 0, "cells_must": 0, "cells_drawn": 0, "cells_settled": 0}
    if _v18_prof_on:
        print(f"[V18-PROFILE] {new_symside} {_v18_floor_cs}: {_v18_prof_why}", flush=True)
    if _v18_brain_on or _v18_floor_on or _v18_prof_on:
        try:
            from tools import v18_brain as _V18B
            _v18_bp = _V18P.learn_file(f"v18_brain_{_v18_floor_cs}.json", ROOT, "brain")
            _v18_brain = _V18B.PilotBrainV18(_v18_bp, new_symside) if _v18_bp.exists() else None
            if _v18_brain is not None:
                _v18_brain.observe_ctx(tier=_tier_name, bh=bh)
            print(f"[V18-BRAIN] {new_symside} model={_v18_bp.name if _v18_brain is not None else None} at={(_v18_brain.meta.get('at') if _v18_brain is not None else None)} allocator={'ON' if (_v18_brain_on and _v18_brain is not None) else 'OFF'} untried_p={_v18_untried_p}", flush=True)
        except Exception as _v18be:
            print(f"[V18-BRAIN-WARN] {new_symside} load {_v18be} — full board, floor without pair evidence", flush=True)
            _v18_brain = None
    _v18_round = os.environ.get("V15_DEFAULTS_ROUND", "")
    def _v18_pair_n(sname: str, rk: str, h):
        if _v18_brain is None:
            return None
        try:
            return float(_v18_brain.decide(sname, rk, str(h).strip(), _v18_round)["n"])
        except Exception:
            return None
    def _v18_floor_keep_fn(sname: str, switch, cand):
        _rk = f"{str(switch).strip()}={str(cand).strip()}"
        def _keep(kind, h):
            _u = _V18P.floor_draw(_v18_floor_cs, new_symside, sname, _rk if kind == "row" else f"{_rk}@{str(h).strip()}", _brain_rid)
            if kind != "row":
                _n = _v18_pair_n(sname, _rk, h)
                if _n is not None and _n < 3:
                    _v18_untried_tot["untried_seen"] += 1
                    _kp = _u < max(_v18_floor_p, _v18_untried_p)
                    _v18_untried_tot["untried_kept"] += 1 if _kp else 0
                    return _kp
            return _u < _v18_floor_p
        return _keep
    def _v18_profile_cells(info: dict, sname: str, switch, cand):
        # V18_PROFILE_YELLOWS: the row's yellow set = needed U suffocating U evidence_pos (+ linknet proposals) of THIS
        # cat_side's profile, plus a floor / untried draw over every other discovered column (never zero); INERT / DAMAGING
        # switches (n_syms >= threshold) keep naked + floor only; the rest is settled with its p (row record v18_profile)
        _rk = f"{str(switch).strip()}={str(cand).strip()}"
        _ent = (_v18_prof or {}).get("needed", {}).get(_rk)
        if _ent is None:
            return
        _prow = (_v18_prof_rows or {}).get(_rk) or {}
        _untried_sw = str(_prow.get("state") or _prow.get("verdict") or "") in ("UNTRIED", "UNTESTED")
        pool = list(dict.fromkeys(list(info["hdrs"]) + [h for _l in _V18P.FLOOR_CELL_LISTS for h in (info.get(_l) or [])]))
        ps = {}
        def _kf(h):
            _n = _v18_pair_n(sname, _rk, h)
            _pe = _v18_untried_p if (_untried_sw or (_n is not None and _n < 3)) else max(_V18P.floor_p(), 0.001)
            ps[h] = _pe
            return _V18P.floor_draw(_v18_floor_cs, new_symside, sname, f"{_rk}@{str(h).strip()}", _v18_round) < _pe
        keep, rest, why = _V18P.profile_select(pool, _ent, _prow, ((_v18_prof or {}).get("proposals") or {}).get(_rk) or [], _kf, _v18_prof_min_n)
        for _l in _V18P.FLOOR_CELL_LISTS:
            if _l in info:
                info[_l] = []
        info["hdrs"] = keep
        info["coarse_deferred_filters"] = rest
        info["v18_profile"] = {"mode": why, "pool": len(pool), "kept": len(keep), "settled": len(rest), "p": {h: round(ps.get(h, 0.0), 5) for h in rest[:24]}}
        _v18_prof_tot["rows"] += 1
        _v18_prof_tot["rows_dead"] += 1 if why != "PROFILE" else 0
        _v18_prof_tot["cells_pool"] += len(pool)
        _v18_prof_tot["cells_must"] += len(keep) - sum(1 for h in keep if h in ps)
        _v18_prof_tot["cells_drawn"] += sum(1 for h in keep if h in ps)
        _v18_prof_tot["cells_settled"] += len(rest)
    def _v18_brain_cells(info: dict, sname: str, switch, cand):
        # V18 brain allocator on this row's cells: evidenced pair -> brain p; untried pair -> V18_UNTRIED_PER_1000; skipped
        # cells ride prior_skipped (PRIOR-REVIVED on a positive naked) and get their p in _v18_brain_p (SETTLE lines below)
        _rk = f"{str(switch).strip()}={str(cand).strip()}"
        keep_, skip_ = [], []
        for _h in info["hdrs"]:
            d = _v18_brain.decide(sname, _rk, str(_h).strip(), _v18_round)
            _v18_untried_tot["brain_cells_seen"] += 1
            if float(d.get("n") or 0.0) < 3:
                _v18_untried_tot["untried_seen"] += 1
                _pe = _v18_untried_p
                _kp = _V18P.floor_draw(_v18_floor_cs, new_symside, sname, f"{_rk}@{str(_h).strip()}", _v18_round) < _pe
                _v18_untried_tot["untried_kept"] += 1 if _kp else 0
            else:
                _pe, _kp = float(d["p"]), bool(d["keep"])
            _v18_brain_p[(sname, str(_h))] = round(_pe, 6)
            (keep_ if _kp else skip_).append(_h)
        if skip_:
            _v18_untried_tot["brain_cells_out"] += len(skip_)
            info["hdrs"] = keep_
            info["prior_skipped"] = list(info.get("prior_skipped") or []) + skip_
            info["v18_brain_skipped"] = list(skip_)
    def _row_static(sname: str, rr: int, switch, cand) -> dict:
        # structural class + this row's yellow cells (read once; the running set is applied at eval time)
        k = (sname, rr)
        if k in _static_info:
            return _static_info[k]
        ws = wb[sname]
        info = {"kind": "eval", "reason": "", "hdrs": [], "h2f": {}, "pending_wiring": [], "yellow": set()}
        _a_font = ws.cell(row=rr, column=1).font
        if cand is None or str(cand).strip() in ("", "None", "none"):
            info.update(kind="skip", reason="NO_CANDIDATE: empty B cell in template row — nothing to test", g=None)
        elif str(switch).strip() in UNWIRED_SWITCHES or str(switch).strip() in UNWIRED_FILTERS:
            info.update(kind="skip", reason="NOT_WIRED_VEC: no reachable vectorized read and the ledger never moved (v15_zero_audit) — not calculated, never a fake 0", g=None)
        elif str(switch).strip().startswith("ABLATION_") and str(cand).strip().lower() in ("true", "1", "yes", "on"):
            # USER 2026-10-08: "ABLATION can never be on unless for a momentary test" — a sweep is not that; 73 live sym_sides had
            # ABLATION_DISABLE_*=True promoted per-sym from these rows (stripped 17:4xZ). Never calculated, never promoted.
            info.update(kind="skip", reason="ABLATION_NEVER_ON: ablation kills are engine artefacts, not strategy (USER 2026-10-08) — not calculated, never promoted", g=None)
        elif str(switch).strip() in GLOBAL_ONLY_KEYS:
            info.update(kind="skip", reason="NOT_IN_CONFIG: GLOBAL_ONLY key (never a per-sym / board override, USER 2026-10-13) — not calculated, never promoted", g=None)
        elif str(switch).strip() == "MAX_AUGMENTS_PER_POSITION" and _maxaug_is_zero(str(cand)):
            # USER 2026-10-10: "MAX_AUGMENTS_PER_POSITION=0 NOT MY CODE — we augment as rapidly and fast as we can"
            # (2026-05-30 no-cap mandate, config 999999). A sweep delta is not a mandate override; never calculated, never promoted.
            # 2026-10-13: extended to fractional <1 ("0.5" bypassed the ("0","0.0") check, promoted 10-12, coerced to 0 — voided as phantom).
            info.update(kind="skip", reason="MAXAUG_NEVER_ZERO: 0 augments contradicts the user no-cap mandate (config 999999) — not calculated, never promoted", g=None)
        elif str(cand).strip().upper().endswith("_ALT"):
            info.update(kind="skip", reason="INVENTED_ALT: *_ALT option value exists in no config — grey, not calculated", g=None)
            ws.cell(row=rr, column=2).font = Font(name="Arial", size=10, color="FFBFBFBF")
        elif not all(k in known_config_fields() for k in (_switch_overrides(str(switch).strip(), _parse_opt_value(cand, defaults.get(switch))) or {str(switch).strip(): None})):
            info.update(kind="skip", reason="NOT_IN_CONFIG: no config/config_tradier/QuickConfig field — grey, not calculated", g=None)
        elif _v17_on and _carry_book and not str(switch).strip().startswith(("GOLDEN_RULE_", "ENTRY_DC_TF", "TECHNICAL_DC_", "DAYTRADE_DC_", "ULTIMATE_DC_4H", "WT_DC_", "DELTA_EXIT", "AUGMENT_", "MAX_AUGMENTS_PER_POSITION", "REENTRY_ON_EXIT_PRICE_BREAK_ENABLED", "REENTRY_ON_DC4_15M_BREAK_ENABLED", "REENTRY_ON_HIGHER_LOW_ENABLED", "SESSION_OPEN_STOP_REFREEZE_ENABLED")) and carry_decide(_carry_book, carry_key(sname, switch, cand), _carry_fp, _t.time(), _tier_name, int(_carry_book.get("boards") or 0)):
            info.update(kind="skip", reason=f"CARRIED_DEAD: |naked|<eps on this sym_side's last {(_carry_book.get('rows') or {}).get(carry_key(sname, switch, cand), [0])[0]} boards (NO-RETEST §65, USER 2026-10-14) — not re-evaluated, re-checked by rotation", g=None)
            _carry_rows[carry_key(sname, switch, cand)] = ("carried", None)
        elif _v17_on and _carry_book and carry_decide(_carry_book, carry_key(sname, switch, cand), _carry_fp, _t.time(), _tier_name, 0, rotate=False):
            info["carry_sampled"] = True  # eligible but rotated in: its fresh naked eval measures the carry precision live
            ws.cell(row=rr, column=1).font = Font(name="Arial", size=10, color="FFBFBFBF")
        elif (_tm_why := _switch_type_violation(str(switch).strip(), cand, defaults)):
            info.update(kind="skip", reason=f"{_tm_why} — grey, not calculated", g=None)
            ws.cell(row=rr, column=1).font = Font(name="Arial", size=10, color="FFBFBFBF")
        elif _brain_naked and (_bro := _brain_row_out(sname, switch, cand)):
            info.update(kind="skip", reason=_bro, g=None)
        else:
            _row_disc(info, sname, switch, cand)
        if _v18_floor_on and info["kind"] == "skip" and str(info.get("reason") or "").startswith(("CARRIED_DEAD", "BRAIN_SAMPLED_OUT")) and not info["hdrs"]:
            _row_disc(info, sname, switch, cand)  # V18 floor: a row skipped before discovery still gets its cells' own floor draws
        if _inert_effective and info["kind"] == "eval" and info["hdrs"] and str(switch).strip() not in _inert_effective:
            if inert_row_sampled(rr, sname, _inert_seq, _inert_every):
                info["inert_sampled"] = True
                _inert_stats["sampled"] += 1
            else:
                info["inert_filters"] = list(info["hdrs"])
                info["hdrs"] = []
                _inert_stats["pruned"] += 1
                _inert_stats["yellows_skipped"] += len(info["inert_filters"])
        if _prior and info["kind"] == "eval" and info["hdrs"]:
            try:
                _pk = (sname, str(switch).strip(), str(cand).strip())
                _pnew = bool(((_prior_psj or {}).get(f"{sname}!{_pk[1]}={_pk[2]}") or {}).get("new"))
                _px = str(switch).strip().startswith(SACRED_ZERO_EXEMPT_PREFIXES) or str(switch).strip() in ESSENTIAL_GATE_SWITCHES or _pnew or f"{sname}!{_pk[1]}={_pk[2]}" in _coarse_expand
                _pmode, _pkept, _pskip, _pmeta = prior_row_policy(_prior, sname, switch, cand, info["hdrs"], rr, _inert_seq, _PRIOR_ROTATE_EVERY, _PRIOR_MIN_N, _px, strict=_tier_strict)
                info["prior_mode"] = _pmode
                if _pskip:
                    info["hdrs"] = _pkept
                    info["prior_skipped"] = list(_pskip)
                    _prior_stats["cells_skipped"] += len(_pskip)
                    _prior_stats["naked_only" if _pmode == "naked_only" else "trimmed"] += 1
                    _prior_book["rows" if _pmode == "naked_only" else "cells"][f"{sname}!{_pk[1]}={_pk[2]}"] = {"mode": _pmode, "why": _pmeta.get("why"), "n": len(_pskip), "verdict": _pmeta.get("verdict")}
                elif _pmode == "rotate":
                    _prior_stats["rotated"] += 1
                info["prior_rank"] = {h: _prior_rank(_prior_entry(_prior, "filter_opt", str(h).strip())) for h in info["hdrs"]}
            except Exception as _pre:
                print(f"[PRIOR-WARN] {sname}!{rr} {_pre} — row calculated", flush=True)
        if _brain is not None and info["kind"] == "eval" and info["hdrs"] and not _brain_exempt(sname, switch, cand):
            try:
                _rk = f"{str(switch).strip()}={str(cand).strip()}"
                _bkeep, _bskip = [], []
                for _h in info["hdrs"]:
                    _pe, _pp, _n = _brain.p_cell(sname, _rk, _h)
                    _brain_stats["cells_seen"] += 1
                    if _brain_draw(new_symside, sname, _rk + "|" + str(_h), _brain_rid) < _pe:
                        _bkeep.append(_h)
                    else:
                        _bskip.append(_h)
                        _brain_book["cells"][f"{sname}!{_rk}@{_h}"] = round(_pe, 5)
                if _bskip:
                    _brain_stats["cells_out"] += len(_bskip)
                    info["hdrs"] = _bkeep
                    info["prior_skipped"] = list(info.get("prior_skipped") or []) + _bskip  # PRIOR-REVIVED path: a positive naked runs them on the spot
                    info["brain_skipped"] = list(_bskip)
            except Exception as _bre:
                print(f"[BRAIN-WARN] cells {sname}!{rr} {_bre} — cells calculated", flush=True)
        if info["kind"] == "eval" and (_ps_on or _redo_heal or _COARSE_FIRST_PASS):
            try:
                _pp, _nn, _isd = _ps_row_ev(ws, rr, sname, switch, cand)
                if _isd:
                    _ps_count(sname, "default", True)
                elif not _ps_on and not _redo_heal:
                    # USER 2026-10-13 V16 SPEED: the coarse cap rode on possym sampling, so V15_POSSYM_SAMPLING=0
                    # silently ran every row with its full ~205-yellow matrix (rows >10s = 40% of fill time).
                    # Pass 1 keeps the top-K prior-ranked yellows; a MOVING row evaluates its deferred cells
                    # inline vs the same chain state (COARSE-INLINE), the rest go to the FOCUS round (round 2).
                    from tools.v15_cat_avg_matrix import norm_cand as _prio_norm
                    _prio_rk = f"{sname}!{str(switch).strip()}={_prio_norm(cand)}"
                    _kept = []
                    _kept_ev = {}
                    for _h in info["hdrs"]:
                        _f, _o = _h.split("=", 1)
                        _kept.append(_h)
                        if _is_none_priority(_prio, f"{_prio_rk}@{_h}"):
                            _kept_ev[_h] = (9999, 9999)
                            continue
                        _fp, _fn = _ps_filter_ev(sname, _f.strip(), _o.strip(), _pp, _nn)
                        try:
                            _kept_ev[_h] = (int(_fp), int(_fn))
                        except Exception:
                            _kept_ev[_h] = (0, 0)
                    if (sname, str(switch).strip(), str(cand).strip()) not in _ps_new and f"{sname}!{str(switch).strip()}={str(cand).strip()}" not in _coarse_expand and not _coarse_cap_exempt(switch) and len(_kept) > _COARSE_CAP > 0:
                        _kept, _deferred = _coarse_trim(_kept, _kept_ev, _COARSE_CAP)
                        for _dh in _deferred:
                            info.setdefault("coarse_deferred_filters", []).append(_dh)
                            _ps_count(sname, "coarse_deferred", False, "cell")
                    info["hdrs"] = _kept
                elif _redo_heal:
                    # USER 2026-10-10 HEAL-COARSE: the heal runs sample-free (deterministic re-skip) but
                    # evidence-capped (top-K prior-ranked yellows, rest deferred) — minutes, not hours.
                    # Naked always evaluates; promoted rows earn the full matrix via _coarse_expand.
                    from tools.v15_cat_avg_matrix import norm_cand as _prio_norm
                    _prio_rk = f"{sname}!{str(switch).strip()}={_prio_norm(cand)}"
                    _kept = []
                    _kept_ev = {}
                    for _h in info["hdrs"]:
                        _f, _o = _h.split("=", 1)
                        if _is_none_priority(_prio, f"{_prio_rk}@{_h}"):
                            _kept.append(_h)
                            _kept_ev[_h] = (9999, 9999)
                            continue
                        _fp, _fn = _ps_filter_ev(sname, _f.strip(), _o.strip(), _pp, _nn)
                        _kept.append(_h)
                        try:
                            _kept_ev[_h] = (int(_fp), int(_fn))
                        except Exception:
                            _kept_ev[_h] = (0, 0)
                    if _COARSE_ON and (sname, str(switch).strip(), str(cand).strip()) not in _ps_new and f"{sname}!{str(switch).strip()}={str(cand).strip()}" not in _coarse_expand and not _coarse_cap_exempt(switch) and len(_kept) > _COARSE_CAP > 0:
                        _kept, _deferred = _coarse_trim(_kept, _kept_ev, _COARSE_CAP)
                        for _dh in _deferred:
                            info.setdefault("coarse_deferred_filters", []).append(_dh)
                            _ps_count(sname, "heal_coarse_deferred", False, "cell")
                    info["hdrs"] = _kept
                else:
                    _go, _bk, _pr, _uu = _possym_decide(new_symside, sname, f"{str(switch).strip()}={str(cand).strip()}", _ps_round, _pp, _nn, (sname, str(switch).strip(), str(cand).strip()) in _ps_new)
                    _ps_count(sname, _bk, _go)
                    if _pr is not None:
                        info["possym"] = {"pos": int(_pp), "n": int(_nn), "p": round(_pr, 4), "u": round(_uu, 4)}
                    if not _go:
                        info.update(kind="skip", reason=f"SKIPPED_SAMPLING(pos_sym={int(_pp)})", g=None)
                    else:
                        _kept = []
                        _kept_ev = {}
                        from tools.v15_cat_avg_matrix import norm_cand as _prio_norm
                        _prio_rk = f"{sname}!{str(switch).strip()}={_prio_norm(cand)}"
                        for _h in info["hdrs"]:
                            _f, _o = _h.split("=", 1)
                            if _is_none_priority(_prio, f"{_prio_rk}@{_h}"):
                                _ps_count(sname, "none_priority", True, "cell")
                                _kept.append(_h)
                                _kept_ev[_h] = (9999, 9999)
                                continue
                            _fp, _fn = _ps_filter_ev(sname, _f.strip(), _o.strip(), _pp, _nn)
                            _fgo, _fbk, _, _ = _possym_decide(new_symside, sname, f"{str(switch).strip()}={str(cand).strip()}@{_h}", _ps_round, _fp, _fn, (sname, _f.strip(), _o.strip()) in _ps_new or (sname, str(switch).strip(), str(cand).strip()) in _ps_new)
                            _ps_count(sname, _fbk, _fgo, "cell")
                            if _fgo:
                                _kept.append(_h)
                                try:
                                    _kept_ev[_h] = (int(_fp), int(_fn))
                                except Exception:
                                    _kept_ev[_h] = (0, 0)
                            else:
                                info.setdefault("sampled_filters", []).append(_h)
                        if _COARSE_ON and not _redo_heal and (sname, str(switch).strip(), str(cand).strip()) not in _ps_new and f"{sname}!{str(switch).strip()}={str(cand).strip()}" not in _coarse_expand and not _coarse_cap_exempt(switch) and len(_kept) > _COARSE_CAP > 0:
                            _kept, _deferred = _coarse_trim(_kept, _kept_ev, _COARSE_CAP)
                            for _dh in _deferred:
                                info.setdefault("coarse_deferred_filters", []).append(_dh)
                                _ps_count(sname, "coarse_deferred", False, "cell")
                        info["hdrs"] = _kept
            except Exception as _pe:
                print(f"[POSSYM-WARN] {sname}!{rr} {_pe} — row calculated", flush=True)
        if _zero_on and info["kind"] == "eval":
            try:
                _zp, _zn, _zisd = _ps_row_ev(ws, rr, sname, switch, cand)
                _zrkey = f"{sname}!{str(switch).strip()}={str(cand).strip()}"
                if _zp is None:
                    _zjr = (_zero_row_ev or {}).get(_zrkey)
                    if isinstance(_zjr, dict):
                        _zp, _zn = _zjr.get("pos_sym"), _zjr.get("n_sym")
                _ly_exempt = _zisd or str(switch).strip().startswith(SACRED_ZERO_EXEMPT_PREFIXES) or str(switch).strip() in ESSENTIAL_GATE_SWITCHES
                _ly_row = low_yield_keep(_zp, _zn, _ZERO_MIN_N_ROW, _zrkey, _ps_round) if (_low_yield_on() and not _ly_exempt) else None
                if _ly_row is not None and _ly_row[1] < 1.0:
                    info["low_yield"] = {"tier": _ly_row[2], "p": _ly_row[1], "pos_sym": _zp, "n_sym": _zn, "kept": bool(_ly_row[0])}
                if _ly_row is not None and not _ly_row[0]:
                    info.update(kind="skip", reason=f"ZERO_FORMULA_ROW LOW_YIELD {_ly_row[2]}: pos_sym={_zp}/{_zn} sampled out this round (p={_ly_row[1]:.3f}, rotates per round; settled, booked)", g=None)
                    if _zero_book_enabled():
                        _zero_book["rows"][_zrkey] = _zero_book_entry("row", sname, str(switch).strip(), cand, "", int(_zp or 0), int(_zn or 0), ((_zero_row_ev or {}).get(_zrkey) or {}).get("avg_delta"))
                elif _ly_row is not None:
                    _zkeys = {h: f"{_zrkey}@{str(h).strip()}" for h in info["hdrs"]}
                    _zkept, _zskip = _zero_partition_hdrs(info["hdrs"], _zkeys, _zero_cell_ev, _ZERO_MIN_N_CELL, _ps_round)
                    if _zskip:
                        info["hdrs"] = _zkept
                        info["zero_skipped"] = _zskip
                elif not _zisd and _zero_condemned(_zp, _zn, _ZERO_MIN_N_ROW) and not str(switch).strip().startswith(SACRED_ZERO_EXEMPT_PREFIXES) and str(switch).strip() not in ESSENTIAL_GATE_SWITCHES:
                    _zjr2 = (_zero_row_ev or {}).get(_zrkey) or {}
                    info.update(kind="skip", reason=f"ZERO_FORMULA_ROW: pos_sym=0 in {_zn} syms, never positive — skipped, booked for formula fix (NOT obsolete)", g=None)
                    if _zero_book_enabled():
                        _zero_book["rows"][_zrkey] = _zero_book_entry("row", sname, str(switch).strip(), cand, "", int(_zp), int(_zn), _zjr2.get("avg_delta"))
                else:
                    _zkeys = {h: f"{_zrkey}@{str(h).strip()}" for h in info["hdrs"]}
                    _zkept, _zskip = _zero_partition_hdrs(info["hdrs"], _zkeys, _zero_cell_ev, _ZERO_MIN_N_CELL, _ps_round)
                    if _zskip:
                        info["hdrs"] = _zkept
                        info["zero_skipped"] = _zskip
                        if _zero_book_enabled():
                            for h in _zskip:
                                _zero_book["cells_by_header"].setdefault(str(h).strip(), []).append(_zrkey)
                            _zero_book["cell_rows"][_zrkey] = sorted(str(h).strip() for h in _zskip)
            except Exception as _ze:
                print(f"[ZERO-FORMULA-WARN] {sname}!{rr} {_ze} — row calculated", flush=True)
        if _v17_on and _V17_P2_LEGACY:
            pass  # V17 P2 = the old main pass exactly (same rows, same yellow policy, same chain path); only the hustle eval is dropped
        elif _v17_on and info["kind"] == "eval" and os.environ.get("V15_V17_P2_NAKED_ONLY", "0") != "1" and (info["hdrs"] or info.get("prior_skipped") or info.get("inert_filters") or info.get("coarse_deferred_filters")):
            # V17 P2 ABBREVIATED WORST_FIRST (default): naked every row (§77 real G) + only the top V15_V17_P2_YELLOWS (8)
            # prior-ranked yellows; the rest join the coarse deferral (settled, inline on moving rows, FOCUS in P3). Canary
            # 2026-10-13: naked-only P2 lost most of the joint lift (RLC A 48.7 at row 2000 vs naked-only 22.5 at P2 end).
            _v17_cap = int(os.environ.get("V15_V17_P2_YELLOWS", "8"))
            _v17_p2_cap_hit = bool(_v17_t.get("p2")) and float(os.environ.get("V15_V17_P2_YELLOW_S", "0") or 0) > 0 and (_t.time() - _v17_t["p2"]["t0"]) > float(os.environ.get("V15_V17_P2_YELLOW_S", "0"))  # default OFF: forensics 2026-10-13 — a load-dependent cap dropped exactly the joint cells that won the old arm
            if _v17_p2_cap_hit:
                # V17 main-pass yellow cap: past V15_V17_P2_YELLOW_S of P2 the remaining rows run naked (+ full revive on a
                # positive naked); their cells are coarse-deferred (settled) for the pinpoint round, which is never starved.
                _v17_pool = list(dict.fromkeys(list(info["hdrs"]) + list(info.get("coarse_deferred_filters") or []) + list(info.get("prior_skipped") or []) + list(info.get("inert_filters") or [])))
                info["hdrs"], info["coarse_deferred_filters"], info["prior_skipped"], info["inert_filters"] = [], _v17_pool, [], []
                info["v17_p2_cap"] = True
                _v17_ystats["skipped_cap"] = _v17_ystats.get("skipped_cap", 0) + len(_v17_pool)
            elif os.environ.get("V15_POSSYM_P_SAMPLING", "1") == "1":
                # USER 2026-10-13: "dont switch off yellow cells, just reduce their frequency of calculation from every time
                # (highest pos_sym values) to once in 200 (0 pos_sym)". Pool = kept + coarse-deferred + prior-skipped + inert
                # cells; each cell evaluated with p = v17_cell_p (deterministic draw per cat_side|tab|row|cell|round);
                # a skipped cell is SAMPLED_SKIP = coarse-deferred (settled, never hollow) and revives on a positive naked.
                _v17_pool = list(dict.fromkeys(list(info["hdrs"]) + list(info.get("coarse_deferred_filters") or []) + list(info.get("prior_skipped") or []) + list(info.get("inert_filters") or [])))
                _v17_keep, _v17_skip = [], {}
                for _h in _v17_pool:
                    _p = 1.0 if str(_h).split("=", 1)[0].strip() in _v17_hv_filters else v17_cell_p(_prior_entry(_v17_prior, "filter_opt", str(_h).strip()), _v17_ptop[0], _PRIOR_MIN_N)
                    if v17_cell_keep(_v17_cs, sname, switch, cand, _h, _inert_seq, _p):
                        _v17_keep.append(_h)
                    else:
                        _v17_skip[_h] = round(_p, 4)
                info["hdrs"] = _v17_keep
                info["coarse_deferred_filters"] = list(_v17_skip)
                info["sampled_skip_p"] = _v17_skip
                info["prior_skipped"] = []
                info["inert_filters"] = []
                _v17_ystats["evaluated"] += len(_v17_keep)
                _v17_ystats["skipped"] += len(_v17_skip)
            elif len(info["hdrs"]) > _v17_cap >= 0:
                _v17_pr = info.get("prior_rank") or {}
                _v17_keep = set(sorted(info["hdrs"], key=lambda h: _v17_pr.get(h, (0, 0.0)), reverse=True)[:_v17_cap])
                info["coarse_deferred_filters"] = list(info.get("coarse_deferred_filters") or []) + [h for h in info["hdrs"] if h not in _v17_keep]
                info["hdrs"] = [h for h in info["hdrs"] if h in _v17_keep]
        elif _v17_on and info["kind"] == "eval" and os.environ.get("V15_V17_P2_NAKED_ONLY", "0") == "1":
            # V17 P2 NAKED-ONLY mode (V15_V17_P2_NAKED_ONLY=1): naked every row (§77 real G); the row's yellow cells (kept +
            # coarse-deferred + prior-skipped + inert) are DEFERRED_V17 = settled (never hollow, never refilled) for P3.
            _v17_def = list(dict.fromkeys(list(info["hdrs"]) + list(info.get("coarse_deferred_filters") or []) + list(info.get("prior_skipped") or []) + list(info.get("inert_filters") or [])))
            if _v17_def:
                info["v17_deferred"] = _v17_def
                info["hdrs"] = []
                info["coarse_deferred_filters"] = []
                info["prior_skipped"] = []
                info["inert_filters"] = []
        if _v18_prof_on and _v18_prof is not None and info["kind"] == "eval":
            try:
                _v18_profile_cells(info, sname, switch, cand)
            except Exception as _v18pce:
                print(f"[V18-PROFILE-WARN] {sname}!{rr} {_v18pce} — row unchanged", flush=True)
        if _v18_brain_on and _v18_brain is not None and not _brain_exempt(sname, switch, cand):
            try:
                _v18_rk = f"{str(switch).strip()}={str(cand).strip()}"
                if info["kind"] == "eval" and _tier_name != "WINNER":
                    _v18_rd = _v18_brain.decide(sname, _v18_rk, None, _v18_round)
                    _v18_untried_tot["brain_rows_seen"] += 1
                    if not _v18_rd["keep"]:
                        _v18_untried_tot["brain_rows_out"] += 1
                        info.update(kind="skip", reason=f"BRAIN_SAMPLED_OUT: V18 p_pos={_v18_rd['p_pos']:.4f} p_eval={_v18_rd['p']:.4f} n={_v18_rd['n']:g} (settled; floor-rotated, never a fake 0)", g=None)
                        info["v18_brain_row_p"] = round(float(_v18_rd["p"]), 6)
                if info["kind"] == "eval" and info["hdrs"] and info.get("v18_profile") is None:  # a profiled row's set is final
                    _v18_brain_cells(info, sname, switch, cand)
            except Exception as _v18bce:
                print(f"[V18-BRAIN-WARN] {sname}!{rr} {_v18bce} — row calculated", flush=True)
        if _v18_floor_on:
            try:
                _V18P.floor_add(_v18_floor_tot, _V18P.floor_apply(info, _v18_floor_keep_fn(sname, switch, cand), _v18_floor_p))
            except Exception as _v18fe:
                print(f"[V18-FLOOR-WARN] {sname}!{rr} {_v18fe} — row unchanged", flush=True)
        if _v18_must_rows or _v18_must_cells:
            _v18_mk = f"{str(switch).strip()}={str(cand).strip()}"
            if _v18_mk in _v18_must_rows or any(_c0 == _v18_mk for _c0, _ in _v18_must_cells):
                try:  # USER LAW: a MUST item is evaluated at p = 1 — no floor / brain / profile / prior skip may remove it
                    if info["kind"] == "skip" and not info["hdrs"] and str(info.get("reason") or "").startswith(("CARRIED_DEAD", "BRAIN_SAMPLED_OUT")):
                        _row_disc(info, sname, switch, cand)
                    _fl_keep = info.get("v18_floor")
                    _V18P.floor_apply(info, lambda kind, h, _m=_v18_mk: (_m in _v18_must_rows) if kind == "row" else ((_m, str(h).strip()) in _v18_must_cells), 1.0)
                    info["v18_must"] = True
                    if _fl_keep is not None:
                        info["v18_floor"] = _fl_keep
                except Exception as _v18me:
                    print(f"[V18-MUST-WARN] {sname}!{rr} {_v18me}", flush=True)
        if _v18_ln and f"{str(switch).strip()}={str(cand).strip()}" in _v18_ln_rows:
            _v18_lk = f"{str(switch).strip()}={str(cand).strip()}"
            try:  # V18_LINKNET_FIRST: the linknet's ranked untried pairs of this row are the first trials (p = 1); a PREDICTION, judged by the engine
                if info["kind"] == "skip" and not info["hdrs"] and str(info.get("reason") or "").startswith(("CARRIED_DEAD", "BRAIN_SAMPLED_OUT")):
                    _row_disc(info, sname, switch, cand)
                _fl_keep2 = info.get("v18_floor")
                _h0 = set(info["hdrs"])
                _V18P.floor_apply(info, lambda kind, h, _m=_v18_lk: False if kind == "row" else ((_m, str(h).strip()) in _v18_ln), 1.0)
                if _fl_keep2 is not None:
                    info["v18_floor"] = _fl_keep2
                for _h in info["hdrs"]:
                    _e = _v18_ln.get((_v18_lk, str(_h).strip()))
                    if _e is not None:
                        _v18_ln_book[(sname, rr, str(_h))] = {"linknet_rank": _e["rank"], "p_pos_pred": _e["p_pos_pred"]}
                        _v18_ln_tot["cells_forced"] += 0 if _h in _h0 else 1
            except Exception as _v18le:
                print(f"[V18-LINKNET-WARN] {sname}!{rr} {_v18le}", flush=True)
        if _v18_brain_on and _v18_brain is not None:
            _v18_rk2 = f"{str(switch).strip()}={str(cand).strip()}"
            if info["kind"] == "skip" and info.get("v18_brain_row_p") is not None:
                _delta_log({"ts": utcnow(), "sym_side": new_symside, "label": "SETTLE", "code": "BRAIN_SKIP", "sheet": sname, "row": rr, "key": _v18_rk2, "filter": None, "p": info["v18_brain_row_p"], "round": _v18_round})
            for _h in info.get("v18_brain_skipped") or []:
                if _h not in info["hdrs"]:
                    _delta_log({"ts": utcnow(), "sym_side": new_symside, "label": "SETTLE", "code": "BRAIN_SKIP", "sheet": sname, "row": rr, "key": _v18_rk2, "filter": str(_h), "p": _v18_brain_p.get((sname, str(_h))), "round": _v18_round})
        _static_info[k] = info
        return info
    def _row_plan(sname: str, rr: int, switch, cand) -> dict:
        # eval items for this row against the CURRENT running set (cumulative_overrides)
        st = _row_static(sname, rr, switch, cand)
        if st["kind"] != "eval":
            return {"static": st}
        cand_parsed = _parse_opt_value(cand, defaults.get(switch))
        sw_ov = _switch_overrides(switch, cand_parsed)
        is_running = all(_same_val(cumulative_overrides.get(k2, defaults.get(k2)), v2) for k2, v2 in sw_ov.items())
        sv = dict(cumulative_overrides)
        sv.update(sw_ov)
        sv, _ = sanitize_overrides(sv, defaults)
        items = [] if is_running else [("naked", sv)]
        hv = dict(initial_overrides)
        hv.update(sw_ov)
        hv, _ = sanitize_overrides(hv, defaults)
        if not is_running and not _v17_on and any(not _same_val(initial_overrides.get(k2, defaults.get(k2)), v2) for k2, v2 in sw_ov.items()):  # V17: F = this row's result vs the ORIGINAL baseline (§56 wording), no second eval
            items.append(("hustle", hv))
        for hdr in st["hdrs"]:
            f = st["h2f"][hdr]
            v = dict(sv)
            v[f["filter"]] = _parse_opt_value(f["opt"], defaults.get(f["filter"]))
            items.append((hdr, sanitize_overrides(v, defaults)[0]))
        return {"static": st, "cand_parsed": cand_parsed, "sw_ov": sw_ov, "is_running": is_running, "switch_variant": sv, "items": items}
    inflight: dict = {}
    _slow_secs: dict = {}
    _SLOW_RED_S = float(os.environ.get("V15_SLOW_CELL_S", "2.0"))  # USER 2026-10-10 throughput hotfix (0.1 -> 2.0: 0.2s cells are normal, were all going RED + 120s retry); re-applied 2026-10-12 after it was lost
    _BATCH_N = max(1, int(os.environ.get("V15_POOL_BATCH_N", "1")))
    _pend_batch: list = []
    def _harvest():
        for ck in [c for c, (f, _) in inflight.items() if f.done()]:
            f, _ = inflight.pop(ck, (None, None))
            if f is None:
                continue
            try:
                _bres = f.result(timeout=0)
                if isinstance(_bres, dict):
                    for _k, (_r, _s, _e) in _bres.items():
                        if not _e:
                            _EVAL_CACHE[_k] = _r
                        inflight.pop(_k, None)
                else:
                    _EVAL_CACHE[ck] = _bres[0]
            except Exception:
                pass
    def _flush_batch():
        # submit pending evals as ONE pool task (shared future across its cks)
        if _pool is None or not _pend_batch:
            return
        batch = _pend_batch[:]
        del _pend_batch[:]
        try:
            fut = _pool.submit(_pool_eval_batch, batch, args.window_days)
        except Exception:
            return
        _now = _t.time()
        for _bck, _bov in batch:
            if _bck not in _EVAL_CACHE and _bck not in inflight:
                inflight[_bck] = (fut, _now)
    def _submit(ov: dict):
        ck = _ck(ov)
        if _pool is not None and ck not in _EVAL_CACHE and ck not in inflight and all(c != ck for c, _ in _pend_batch):
            _v17_evals[0] += 1  # V17 per-phase eval count (real engine evals submitted to the pool)
            _pend_batch.append((ck, ov))
            if len(_pend_batch) >= _BATCH_N:
                _flush_batch()
        return ck
    _spec_state = {"ptr": 0, "ver": 0, "ptr_ver": 0}
    _v18_spec = bool(_V18P is not None and _V18P.spec_batch_on() and _pool is not None)
    _v18_spec_stats = {"discarded": 0, "resubmits": 0}
    _ROW_PRESUBMIT = os.environ.get("V15_ROW_PRESUBMIT", "0") == "1"  # 2026-10-14 throughput lane: default OFF (A/B: +33% CPU, same wall on saturated hosts)
    def _prefetch(qi: int):
        # speculative: rows ahead are submitted vs the CURRENT running set. A promotion changes the running set, so a
        # speculated result can never be used for a different baseline (cache key = the full override set).
        if _pool is None:
            return
        if _v18_spec and _spec_state["ptr_ver"] != _spec_state["ver"]:
            # E5 V18_SPEC_BATCH: the chain moved -> every pending speculative result was computed against the OLD running set;
            # cancel what has not started and resubmit from this row (results are always applied in row order, keyed by
            # the exact full set, so the chain is byte-identical by construction)
            _v18_spec_stats["discarded"] += _V18P.spec_cancel_stale(inflight)
            _v18_spec_stats["resubmits"] += 1
            del _pend_batch[:]
        if _spec_state["ptr_ver"] != _spec_state["ver"] or _spec_state["ptr"] <= qi:
            _spec_state["ptr"], _spec_state["ptr_ver"] = qi, _spec_state["ver"]
        # 2026-10-13 THROUGHPUT (USER ">12 boards/server/hour"): the cap counts distinct pool TASKS — with V15_POOL_BATCH_N=8
        # (scheduler env) 8 evals share one future, and counting entries capped the pipeline at ONE task (S1 HOOD_SHORT: 4
        # workers 87% idle, main 88% waiting, ~1 core per board). Pending partial batches are flushed at the end.
        # A/B S1 2026-10-14 UNIUSDC_SHORT (same file, frozen inputs, concurrent): identical result 26.3989 and wall 25:05 vs 25:04,
        # but +33% CPU (2558 vs 1928 user-s) — the hosts are CPU-saturated (0% idle), so deeper speculation only burns cores.
        # Default OFF; V15_PREFETCH_TASKCAP=1 / V15_ROW_PRESUBMIT=1 for an idle host.
        _taskcap = os.environ.get("V15_PREFETCH_TASKCAP", "0") == "1" or _v18_spec
        _ahead = int(os.environ.get("V15_PREFETCH_ROWS", "200")) if _taskcap else 60
        _cap_busy = 2 * _n_proc
        _end = qi + _ahead
        if _v18_spec:
            _end = _V18P.tab_span(pending_queue, qi, int(os.environ.get("V18_SPEC_ROWS", "400")))  # the whole rest of THIS tab
            _cap_busy = int(os.environ.get("V18_SPEC_TASKS", str(4 * _n_proc)))
        def _busy():
            return len({id(f) for f, _ in inflight.values() if not f.done()}) if _taskcap else sum(1 for f, _ in inflight.values() if not f.done())
        while _spec_state["ptr"] < len(pending_queue) and _spec_state["ptr"] < _end and _busy() < _cap_busy:
            plan = _row_plan(*pending_queue[_spec_state["ptr"]])
            for _lab, _ov in plan.get("items", []):
                _submit(_ov)
            _spec_state["ptr"] += 1
        if _taskcap:
            _flush_batch()
    def _v18_logfields(sname, rr, label):
        _bp = _v18_brain_p.get((sname, str(label)))
        out = {"phase": _V18P.phase_of(sname, label, SWITCH_SHEETS), "brain_p": 1.0 if _bp is None else _bp, "brain_model": (_v18_brain.meta.get("at") if _v18_brain is not None else None)}
        out.update(_v18_lx.get(str(label)) or {})
        out.update(_v18_ln_book.get((sname, rr, str(label))) or {})
        return out
    def _get(sname: str, rr: int, switch, cand, label: str, ov: dict, deadline: float, cum_before: float):
        # one real evaluate_prepared_sanitized result (pool / cache / serial thread), hard deadline, one DELTA-LOG line
        ck = _ck(ov)
        t0 = _t.time()
        res, err, cached = None, "", False
        if ck not in _EVAL_CACHE and _pool is None:
            _v17_evals[0] += 1  # V17 per-phase eval count (serial path; pool evals are counted at submit)
        if ck in _EVAL_CACHE:
            res, cached = _EVAL_CACHE[ck], True
            if _v18_ids is not None and _v18_ids.settle(hash(ck), cum_before, label) is not None:
                return res, err
        elif _pool is not None:
            _cp = _get_critical_pool(ck, _prio_pool, _EVAL_CACHE, inflight, _pend_batch)
            if _cp is not None:
                try:  # TASK 05.2: this critical-path eval jumps the shared FIFO on its own worker (V15_PRIORITY_LANE=1)
                    inflight[ck] = (_cp.submit(_pool_eval_batch, [(ck, ov)], args.window_days), _t.time())
                except Exception:
                    pass
            _submit(ov)
            _flush_batch()
            if ck in inflight:
                fut, _ = inflight[ck]
            else:
                # submit failed (broken / shutting-down pool, e.g. SIGTERM reached the workers): an honest missing verdict,
                # never a KeyError that aborts the whole phase (production AMZN_LONG 2026-10-13 lost its pinpoint round)
                fut = _cf.Future()
                fut.set_exception(RuntimeError("pool unavailable (submit failed)"))
            try:
                _bres = fut.result(timeout=max(0.01, deadline - _t.time()))
                if isinstance(_bres, dict):
                    for _k, (_r, _s, _e) in _bres.items():
                        if not _e:
                            _EVAL_CACHE[_k] = _r
                    _it = _bres.get(ck, (None, 0.0, "ERR missing"))
                    res, _secs, _berr = _it[0], _it[1], _it[2]
                    if _berr:
                        err = _berr[:120]
                else:
                    res, _secs = _bres
                    _EVAL_CACHE[ck] = res
                try:
                    _wsecs = float(_secs) if _secs is not None else 0.0
                except Exception:
                    _wsecs = 0.0
                if _wsecs > _SLOW_RED_S:
                    _slow_secs[(sname, rr, label)] = _wsecs
                    if label in ("naked", "hustle") or str(label).startswith(("JOINT:", "RECALC", "RED_RETRY:")):
                        print(f"[slow-cell] {sname}!{rr} {label} worker_secs={_wsecs:.3f} >{_SLOW_RED_S} (non-yellow: logged, no paint)", flush=True)
            except _cf.TimeoutError:
                err = f"TIMEOUT {YELLOW_TIMEOUT:.0f}s"
                fut.cancel()
            except Exception as _fe:
                err = f"ERR {_fe}"[:120]
            inflight.pop(ck, None)
        else:
            ex = _cf.ThreadPoolExecutor(max_workers=1)
            try:
                from tools.opt import v12_pilot as _vp
                if prepared is not None:
                    fut = ex.submit(_vp.evaluate_prepared_sanitized, prepared, ov, args.window_days)
                else:
                    fut = ex.submit(_vp.evaluate_sanitized, new_symside, ov, window_days=args.window_days)
                res = fut.result(timeout=max(0.01, deadline - _t.time()))
                _EVAL_CACHE[ck] = res
            except _cf.TimeoutError:
                err = f"TIMEOUT {YELLOW_TIMEOUT:.0f}s"
            except Exception as _se:
                err = f"ERR {_se}"[:120]
            finally:
                ex.shutdown(wait=False)
        g = (res or {}).get("gain_pct")
        _delta_log({**(_v18_logfields(sname, rr, label) if _v18_logx[0] else {}), "ts": utcnow(), "sym_side": new_symside, "nav": "sequential", "sheet": sname, "row": rr, "switch": switch, "cand": str(cand), "label": label, "fn": "tools.opt.v12_pilot.evaluate_prepared_sanitized", "window_days": args.window_days, "gain_pct": g, "trades": (res or {}).get("trades"), "fp": ((res or {}).get("behavior_fingerprint") or "")[:16], "tim": (res or {}).get("tim_pct"), "max_dd_pct": (res or {}).get("max_dd_pct"), "pool_sharpe": (res or {}).get("pool_sharpe"), "wr_pct": (res or {}).get("wr_pct"), "valid": (res or {}).get("valid"), "invalid_reason": (res or {}).get("invalid_reason"), "cum_before": cum_before, "delta": (float(g) - cum_before) if g is not None else None, "secs": round(_t.time() - t0, 4), "cached": cached, "err": err})  # BRAIN 2026-10-14: dd/sharpe/wr logged (already in the result, zero extra compute) so the graph learns every metric
        if _v18_ids is not None and res is not None and not err:
            _v18_ids.note(hash(ck), cum_before, f"{sname}!{rr}:{label}")
        return res, err
    _delta_vs = delta_vs_result  # module-level pure twin (test_v15_row_guards covers the verdict/settle composition)
    def _num_cell(ws, rr: int, col: int, value, good: bool, bold: bool = True):
        cell = ws.cell(row=rr, column=col)
        cell.value = float(value)
        cell.font = Font(name="Arial", size=10, bold=bold, color="006100" if good else "9C0006")
        cell.fill = PatternFill(fill_type=None)  # USER 2026-09-30: red paint ONLY for stuck/slow cells, never for a negative value
        cell.alignment = VISUAL_ALIGN
    # USER 2026-10-13 (ABSOLUTE) "a worse result is PHYSICALLY IMPOSSIBLE": the best-start set (best of last round vs template
    # defaults, [BEST-START]) is recorded as best_seen BEFORE anything can lower the chain (E3-DEFAULT-BASE below, compliance
    # repair, endgame, diagnose, any V17 phase) — the BEST-SEEN publish gate then never publishes below it. Fresh eval.
    if not (progress.get("best_seen") or {}).get("start_noted"):
        try:
            _st_res, _st_err = _get("START", None, "BEST_START", "", "BEST_START_SET", sanitize_overrides(dict(cumulative_overrides), defaults)[0], _t.time() + YELLOW_TIMEOUT * 6, float(cumulative_gain))
            if _st_res and not _st_err:
                _bs_note("START", cumulative_overrides, _st_res)
                progress.setdefault("best_seen", {})["start_noted"] = True
                progress["best_seen"]["start_gain"] = _st_res.get("gain_pct")
                progress["best_seen"]["start_overrides"] = sanitize_overrides(dict(cumulative_overrides), defaults)[0]  # the BEST-START-FLOOR set
        except Exception as _ste:
            print(f"[BEST-SEEN-warn] {new_symside} start note: {_ste}", flush=True)
    # USER 2026-09-30: the FIRST row is the DEFAULT row. If the override set changes that switch, E3 = the baseline WITHOUT
    # that override (switch at its bold default); the overridden value is re-earned by its own row's delta further down.
    if not progress.get("done") and pending_queue:
        _s0, _r0, _sw0, _c0 = pending_queue[0]
