            try:
                _ct = float((res or {}).get("tim_pct"))
            except Exception:
                _ct = None
            if tim_guard_veto(_ct, chain_tim):
                continue
            try:
                _ctr = int((res or {}).get("trades") or 0)
            except Exception:
                _ctr = None
            if trades_guard_veto(_ctr, chain_trades):
                continue
